\textbf{\textcolor{red}{AIMS OF TIME SERIES ANALYSIS}}

\begin{keydef}
\fcnum{0} $\to$ \textbf{Describe} -- trend, seasonal, cycle 

$\to$ \textbf{Explain} 
- **modeling and inference** write a model and estimate its parameters
- \textbf{Forecast} accounting for uncertainty
\end{keydef}

\textbf{\textcolor{red}{[SYNC-TEST ✓ — if you see this in the app, Claude→file→website works. I will remove it.]}}

\textbf{\textcolor{red}{TIME SERIES DECOMPOSITION}}

\begin{keydef}
\fcnum{1} View $Y_t$ as composed of: a \textbf{Trend}, a \textbf{Seasonal} comp (fixed recurrence), a \textbf{cycle} (AR style modeling), and an \textbf{Erratic} comp.

\textbf{Additive}: $Y_t = T_t + S_t + C_t + E_t$

\textbf{Multiplicative}: $Y_t = T_t \cdot S_t \cdot C_t \cdot E_t$

note $\log$ transforms a multiplicative decomposition into an additive one
\end{keydef}

\textbf{\textcolor{red}{FITTING A TREND}}

\begin{keydef}
For $Y_t = T_t + E_t$ (no seasonal comp.):

\fcnum{2} \textbf{OLS.} 
\textbf{Moving averages.} e.g.\ MA of order $k=3$:
\[ \widehat{T}_t = \frac{y_{t-1} + y_t + y_{t+1}}{3}, t = 2, 3, \dots \]
If $k$ is even, e.g.\ $k = 4$:
\[ \widehat{T}_t = \frac{0.5\, y_{t-2} + y_{t-1} + y_t + y_{t+1} + 0.5\, y_{t+2}}{4}. \]
\end{keydef}

\textbf{\textcolor{red}{DETRENDING}}
\[ y_t^{\text{detrended}} = y_t - \widehat{T}_t. \]

after you detrend, you remove the seasonal coponent

\textbf{\textcolor{red}{FITTING A SEASONAL COMPONENT}}

\begin{keydef}
For $Y_t = S_t + E_t$ (purely seasonal, no trend; assume mean zero, $\bar{y}_t = 0$):

\fcnum{3} \textbf{Seasonal dummies.} Eg use dummies for the month

\textbf{Moving averages.} For monthly data, $\mathrm{MA}(12)$:
$$ y_t^{\text{deseason.}} = \frac{0.5\, y_{t-6} + y_{t-5} + \dots + y_{t+5} + 0.5\, y_{t+6}}{12}. $$
\end{keydef}

\textbf{\textcolor{red}{HOW TO ASSIGN THE PROBABILITY LAW OF THE PROCESS}}



\begin{keydef}
\fcnum{13a} Defining a \textbf{statistical model} for a stoch.\ process $(Y_t)_{t \in T}$ requires specifying its probabilty law $\mathbb{P}$ first.  

Under Kolmogorov's \emph{consistency conditions},  $\mathbb{P}$ can be uniquely identified by the family of \textbf{finite-dimensional distributions (FDDs)}
$$
\Bigl\{
\underbrace{f_{Y_{t_1},\dots,Y_{t_k}}}_{\text{Joint distribution}}
\bigl(
\underbrace{y_1,\dots,y_k}_{\text{evaluated at}}
\bigr)
\;\Big|\;
k\ge1,\ 
(\underbrace{t_1,\dots,t_k}_{\text{at }k\text{ times}})
\in \underbrace{T^k}_{\text{Tuples in T}}
\Bigr\}
$$
\end{keydef}
Basically, you want to know
- The margianl at every t eg $Y_t \sim \mathcal{N}(\mu_t, \sigma_t^2)$ for each $t$. 
- The bivariate densities $p_{s,t}(y_s, y_t)$ capturing dependences eg $\mathrm{Cov}(Y_s, Y_t) = 0$ for $s \neq t$ gives an iid process (under some assumptions); note from the marginals you cannot get the bivariates! (if you do not know how what is the correlation structure)

\textbf{\textcolor{red}{FORECASTING ALGORITHMS — CASES 0, 1, 2}}


\textbf{\textcolor{red}{NEEDS FULL REWRITE TO THE SLIDES}}


Predict $y_{t+1}\mid y_{1:t}$ — often the ultimate goal. At time $t$ define the \textbf{forecast function}$$ f_t : \mathbb{N} \to \mathbb{R}, \qquad f_t(h) = \hat y_{t+h\mid t}, $$i.e.\ $f_t(h)$ is the $h$-step-ahead forecast made using information up to $t$.





Prediction accuracy: 



\begin{keydef}
\fcnum{4} \textbf{MAD} (Mean Absolute Deviation):$$ \mathrm{MAD} = \frac{1}{n} \sum_{t=1}^{n} \left| y_t - \hat{y}_t \right| $$

\textbf{MSE} (Mean Squared Error):$$ \mathrm{MSE} = \frac{1}{n} \sum_{t=1}^{n} \left( y_t - \hat{y}_t \right)^2 $$

\textbf{MAPE} (Mean Absolute Percentage Error):$$ \mathrm{MAPE} = \frac{1}{n} \sum_{t=1}^{n} \left| \frac{y_t - \hat{y}_t}{y_t} \right| $$
\end{keydef}


\textbf{THE ACTUAL ALGORITHMS}


\textbf{Case 0 — Simple exponential smoothing} (SES / EWMA / Holt point predictor). For a non-seasonal series with no systematic trend, predict$y_{t+1}$by a weighted average of the past data with geometrically decaying weights:$$\hat y_{t+1\mid t}=\lambda\sum_{j=0}^{t-1}(1-\lambda)^{j}y_{t-j},\qquad 0\le\lambda<1.$$For large$t$the weights sum to$\approx 1$


\textbf{Case 1 — Holt linear predictor} (local linear trend). Decompose the series into a local level plus a local slope,$y_t=L_t+B_t$, and combine exponentially-smoothed forecasts of level and growth:$$\hat y_{t+k\mid t}=\hat L_{t+1\mid t}+\hat B_{t+1\mid t}\,k,$$$$\hat L_{t+1\mid t}=\lambda y_t+(1-\lambda)(\hat L_{t\mid t-1}+\hat B_{t\mid t-1})=\hat y_{t\mid t-1}+\lambda e_t,$$$$\hat B_{t+1\mid t}=\gamma(\hat L_{t+1\mid t}-\hat L_{t\mid t-1})+(1-\gamma)\hat B_{t\mid t-1}=\hat B_{t\mid t-1}+\lambda\gamma\,e_t.$$The forecast function is now \textbf{linear} in$k$.


\textbf{Case 2 — Holt-Winters} (seasonal). A further extension adds a seasonal component (additive or multiplicative) with its own smoothing parameter, giving the popular Holt and Winters methods (Hyndman et al., 2008).


\textbf{Uncertainty of SES forecasts (May 2022 Q1) — answer: NO.}

SES returns a point forecast only. The empirical methods of Sec.\ 3.1.1 are \textbf{not based on a probabilistic or statistical model} for the observed series, which makes it impossible to assess forecast uncertainty using standard measures like confidence or probability intervals. Hence SES provides no quantification of the uncertainty about its one-step-ahead point forecasts. To attach probability intervals one must embed it in an underlying DLM (e.g.\ the local level model, whose steady-state one-step forecast coincides with SES).

\textbf{\textcolor{red}{STATIONARITY}}

\begin{keydef}
\fcnum{8}  time series $(Y_t)$ is \textbf{stationary} if $E(Y_t)$ and $E(Y_t Y_{t+h})$ exist, are finite, and do not depend on $t$, for every $h = 0, 1, 2, \dots$
$$ \mu(t) = \mu, \qquad \sigma^2(t) = \sigma^2, \qquad \gamma(t, t+h) = \tilde\gamma(h) \quad \text{(autocov.\ depends only on lag } h\text{)}. $$
\end{keydef}

\textbf{\textcolor{red}{STRICT STATIONARITY}}

\begin{keydef}
\fcnum{7}  A time series $(Y_t)_{t \in T}$ is \textbf{strictly stationary} if the joint distribution of $(Y_{t_1}, \dots, Y_{t_k}) \stackrel{d}{=} (Y_{t_1+h}, \dots, Y_{t_k+h}), \qquad \text{for any } (t_1, \dots, t_k) \text{ and } h $
\end{keydef}

Obviously this implies 
- $k = 1$: every $Y_t$ has the same marginal.
- $k = 2$: every bivariate depends on lag only, not on time.
- weak stationarity \emph{(only if $E[Y_t]$ and $E[Y_t^2]$ are finite --- for distributions with no second moment, e.g.\ Cauchy, strict stationarity does NOT imply weak stationarity)}.

\textbf{\textcolor{red}{CONDITIONS OF THEOREM 2.1 — RECURRENT, APERIODIC, IRREDUCIBLE}}

\textbf{Recurrence / transience.}
\begin{keydef}
\fcnum{17a} Consider the Markov chain started at $Y_0 = j$. Let
\[ f_j \;=\; P(\text{the chain returns at least once to } j \mid Y_0 = j). \]

$\bullet$ \textbf{Recurrent}: $f_j = 1$
$\bullet$ \textbf{Transient}: $f_j < 1$
$\bullet$ \textbf{Recurrent non-null}: $f_j = 1$ \emph{and} the expected return time is finite. This is what Theorem 2.1 needs.
\end{keydef}

\textbf{Periodicity.} 
\begin{keydef}
\fcnum{17b} State $j$ has \textbf{period $d$} if a return to $j$ is possible only at multiples of $d$ steps
\end{keydef}

\textbf{Closed set / irreducibility.}
\begin{keydef}
\fcnum{17c} A set $C \subseteq \mathcal{Y}$ is \textbf{closed} if: $p_{j,k} = 0 \quad \text{whenever } j \in C \text{ and } k \notin C.$ 
\textbf{Irreducible Markov Chain} if there are no \emph{proper} closed subsets (i.e.\ no closed subset $C \subsetneq \mathcal{Y}$ --- the whole space $\mathcal{Y}$ is always closed, that doesn't count) $\rightarrow$ equivalently, every state is reachable from every other state in finitely many steps.
\end{keydef}
\emph{Example (reducible chain).} On $\mathcal{Y} = \{1, 2, 3, 4\}$,
\[ \mathbf{P} = \begin{pmatrix} 1/3 & 0 & 2/3 & 0 \\ 0 & 1/4 & 0 & 3/4 \\ 1/2 & 0 & 1/2 & 0 \\ 0 & 1/2 & 0 & 1/2 \end{pmatrix} \]
is reducible: the two sets $C_1 = \{1, 3\}$ and $C_2 = \{2, 4\}$ are each closed (no row in $C_1$ has positive mass on a column in $C_2$, and vice versa). The chain has no common limit distribution --- the long-run behaviour depends on which basin you start in.

\textbf{Consequences for an irreducible chain.}
For an irreducible state: 
$\bullet$ \emph{Class property.} All states share the same recurrence status: either all recurrent, or all transient. 
$\bullet$ \emph{Finite state space.} If $|\mathcal{Y}| < \infty$, at least one state is visited infinitely often = recurrent. By the class property, \emph{all} states are positive recurrent. This guarantees the strict positivity $p^*(k) > 0$ in Theorem 2.1.
$\bullet$ \emph{Aperiodicity is still needed.} Recurrent + irreducible alone is not enough --- a periodic chain (e.g.\ alternating between two states) doesn't converge to a stationary marginal; it oscillates. Theorem 2.1 adds aperiodicity to rule this out.

\textbf{\textcolor{red}{MARKOV PROPERTY}}

\begin{keydef}
\fcnum{15a} A discrete-time stochastic process $(Y_t)_{t \ge 0}$ with $Y_t \in \mathcal{Y}$ is \textbf{Markov} if

$\bullet$ $Y_0 \sim p_0(\cdot)$ \;(initial distribution), and

$\bullet$ for every $t \ge 1$, $Y_t\;\big|\; Y_{t-1},  \;\perp\!\!\!\perp\; (Y_0, Y_1, \dots, Y_{t-2}) $, that is $p(y_t \mid y_{0:t-1}) = \underbrace{p(y_t \mid y_{t-1})}_{\text{Transition Probability}}.$
\textbf{\textcolor{red}{DAG view.}} A Markov chain is naturally drawn as a directed acyclic graph (DAG):$$ Y_0 \to Y_1 \to Y_2 \to \dots \to Y_{t-1} \to Y_t \to \dots $$

The law of the process is fully specified by
$\bullet$ the \textbf{initial distribution} $p_0(\cdot)$ of $Y_0$;
$\bullet$ the family of \textbf{one-step transition probabilities} $\{p_t(y_t \mid y_{t-1}) : t \ge 1\}$.
\end{keydef}



Note how this is always big Y.


Finite state space $\mathcal{Y} = \{1, 2, \dots, M\}$. The transition probabilities at time $t$ are$$ p^{(t)}_{i,j} = P(Y_t = j \mid Y_{t-1} = i), \qquad i, j \in \mathcal{Y}. $$Arrange them in a matrix $\mathbf{P}^{(t)}$. Drop $t$ everywhere if homogeneous.








\begin{keydef}
\fcnum{15b} \textbf{Plugging the Markov property into the previous chain:}

$\bullet$ \emph{Non-homogeneous case} (transition kernel varies with $t$):
$$ p_n(y_0, \dots, y_n) = p_0(y_0) \prod_{t=1}^{n} p_t(y_t \mid y_{0:t-1}) \; \underbrace{=}_{\text{Markov}}\; p_0(y_0) \prod_{t=1}^{n} p_t(y_t \mid y_{t-1}). $$
\end{keydef}

\textbf{\textcolor{red}{BAYESIAN STATISTICS --- Bayes' rule, derivation and intuition}}

You want to know given the data (y), what is the parameter ($\theta$) or the future value ($\hat y$) ?

$$  P(A \mid B) \; \underbrace{=}_{\text{conditional probability}}\; \frac{P(A \cap B)}{P(B)} $$
i.e.\emph{"after seeing evidence $B$, how likely is hypothesis $A$?"}. 
\emph{The problem.} The joint $P(A \cap B)$ is usually hard to compute directly.

Bayes genious idea: 
$$\underbrace{P(A \cap B)}_{\text{hard to compute directly}} \;\;\longleftrightarrow\;\; \underbrace{P(B \mid A) \cdot P(A)}_{\text{both easy: a model + a prior}}. $$

Then ppl gave an interpretation
\begin{keydef}
\fcnum{33} 
$$
\underbrace{P(A \mid B)}_{\text{posterior: belief in } A \text{ \emph{after} seeing } B}
\;=\;
\overbrace{P(A)}^{\text{prior: belief in } A \text{ \emph{before} seeing } B}
\;\cdot\;
\underbrace{
\frac{P(B \mid A)}{P(B)}
}_{\text{evidence multiplier}}
$$
\end{keydef}



Bayes is a form of learning from experience! 




Clearly the denominator is a normalization. That is, if the event $B$ happens with 3\% probability in general and 4\% when $A$ is active, then the evidence is mildly aligned with $A$ being active. \emph{Notice:} say you have a prior of 90\% that somebody is guilty, then you get a nearly irrelevant test that fires "guilty" with 5\% probability in general and 5.1\% on this guy. Does this mean the probability of him being guilty is now 5.1\%? \textbf{No!} You had other proofs that composed that 90\%, and this extra evidence is a tiny new push in favour of him being guilty (multiplier $\approx 5.1/5 = 1.02$, so the posterior moves only marginally above 90\%).

\textbf{\textcolor{red}{BAYESIAN vs FREQUENTIST INFERENCE}}

After deriving Bayes' rule and seeing the prior get \emph{updated} by evidence into a posterior, a natural question arises: \emph{does the prior shift mean there is no true $\theta$?} The answer is no --- but to see why, we need to compare the two frameworks side by side.

\textbf{\textcolor{red}{The status of $\theta$.}}

$\bullet$ \emph{Frequentist.} $\theta$ is a \textbf{fixed unknown constant} of nature. It does not have a probability distribution. Probability is reserved for the data. Not a random variable. Uncertainty is driven by the sampling procedure (we see a different estimate just because the sample is not fully representative of the population)"$P(\hat\theta \in [a, b]) = 0.95$" means: if we repeated the sampling many times, 95\% of the resulting intervals $[\hat a_n, \hat b_n]$ would contain the true $\theta$. Estimator: MLE. 


$\bullet$ \emph{Bayesian.} $\theta$ may also be a fixed unknown constant in nature --- but since we don't \emph{know} it, we represent our \textbf{state of belief} about $\theta$ as a probability distribution: $\pi(\theta)$ before data, $p(\theta \mid y)$ after. The randomness lives in our \emph{knowledge} (is epistemic), not in $\theta$ itself. $\theta$ is a **random variable.**  Estimator: Posterior. 

So the prior shifting does \emph{not} mean $\theta$ moves. It means our \emph{uncertainty about $\theta$} sharpens around the values most compatible with the data. The true $\theta$ (if you believe in one) is a fixed point in parameter space; the probability mass representing our knowledge is what slides around it.


\textbf{\textcolor{red}{Confidence intervals (frequentist) vs Credible intervals (Bayesian).}}

\textbf{\textcolor{red}{Frequentist confidence interval --- exact formula.}} Given an estimator $\hat\theta_n$ with (asymptotic) standard error $\text{SE}(\hat\theta_n)$ (how the estimator estimates would vary across replications of the experiment, derived analytically from the model), the $1 - \alpha$ Wald confidence interval is
\begin{keydef}
\fcnum{32a} Asymptotic distribution of the MLE (Fisher information):
$$ \sqrt{n}\,\bigl(\hat\theta_n - \theta_0\bigr) \;\underbrace{\xrightarrow{d}}_{\text{CLT}}\; \mathcal{N}\!\bigl(0,\; I_1(\theta_0)^{-1}\bigr) \quad \rightarrow \quad \hat\theta_n \;\overset{\mathrm{approx}}{\sim}\; \mathcal{N}\!\Bigl(\theta_0,\; \tfrac{1}{n\, I_1(\theta_0)}\Bigr) \;\underbrace{=}_{\text{iid}}\; \mathcal{N}\!\bigl(\theta_0,\; I_n(\theta_0)^{-1}\bigr). $$
In practice $\theta_0$ is replaced by the plug-in $\hat\theta_n$ (consistency $+$ Slutsky), so the $1-\alpha$ Wald CI reads:
$$ \boxed{\;\text{CI}_{1-\alpha} \;=\; \hat\theta_n \;\pm\; z_{1-\alpha/2}\,\sqrt{I_n(\hat\theta_n)^{-1}}.\;} $$
$z_{1-\alpha/2}$ is the $1 - \alpha/2$ quantile of the standard Normal (e.g.\ $z_{0.975} = 1.96$ for $95\%$).
\end{keydef}





\textbf{\textcolor{red}{Bayesian credible interval --- exact formula.}} A $1 - \alpha$ credible interval is any interval $[a, b]$ such that the posterior probability
\begin{keydef}
\fcnum{32b} $$ P(\, a \le \theta \le b \mid y \,) \;=\; \int_{a}^{b} p(\theta \mid y)\, d\theta \;=\; 1 - \alpha. $$
\emph{Gaussian-posterior closed form} (DLMs: $\theta\mid y\sim\mathcal{N}(m,C)$):
$$ \boxed{\;\text{Bayesian CI}_{1-\alpha} \;=\; m \;\pm\; z_{1-\alpha/2}\,\sqrt{C}.\;} $$
\end{keydef}
Now $y$ is fixed (the observed data) and $\theta$ is the random variable; the probability is over the posterior $p(\theta \mid y)$.

\begin{keydef}

\textcolor{orange}{\textbf{Closed-form filtering for the constant (fixed-}}$\omark{\theta}$\textcolor{orange}{\textbf{) model --- Normal--Normal conjugate update (book Sec.\ 1.2, eqs.\ 1.2--1.4; exams Sept 2025 Q8, June 2022 Q7).}}

\medskip

\textcolor{orange}{\emph{Setup.} The observations are}
$$ \omark{Y_t = \theta + \varepsilon_t, \qquad \varepsilon_t \overset{iid}{\sim} \mathcal{N}(0,\sigma^2), \qquad \theta \sim \mathcal{N}(m_0, C_0),} $$
\textcolor{orange}{with} $\omark{\theta}$ \textcolor{orange}{and the} $\omark{\varepsilon_t}$ \textcolor{orange}{independent. This is the} \emph{random walk plus noise} \textcolor{orange}{with evolution variance} $\omark{W = \sigma_w^2 = 0}$\textcolor{orange}{, so} $\omark{\theta_t = \theta_{t-1} = \theta}$ \textcolor{orange}{is a static parameter and filtering reduces to learning a constant (the book writes} $\omark{\omega}$ \textcolor{orange}{for this fixed mean).}

\medskip

\textcolor{orange}{\emph{(Sept 2025 Q8a) Joint density.} By the conditional-i.i.d.\ structure given} $\omark{\theta}$ \textcolor{orange}{(here} $\omark{\sigma^2 = 1}$\textcolor{orange}{):}
$$ \omark{ p(y_{1:t}, \theta) \;=\; \pi(\theta)\prod_{i=1}^{t} p(y_i \mid \theta) \;=\; \frac{1}{\sqrt{2\pi C_0}}\, e^{-\frac{(\theta - m_0)^2}{2C_0}} \prod_{i=1}^{t} \frac{1}{\sqrt{2\pi}}\, e^{-\frac{(y_i - \theta)^2}{2}}. } $$

\medskip

\textcolor{orange}{\emph{Posterior by Bayes' rule.} The marginal} $\omark{p(y_{1:t})}$ \textcolor{orange}{is a constant in} $\omark{\theta}$\textcolor{orange}{, so}
$$ \omark{ p(\theta \mid y_{1:t}) \;\propto\; \pi(\theta)\prod_{i=1}^{t} p(y_i \mid \theta) \;\propto\; \exp\!\left\{-\tfrac{1}{2}\Big[\big(\tfrac{t}{\sigma^2} + \tfrac{1}{C_0}\big)\theta^2 - 2\big(\tfrac{t\bar y}{\sigma^2} + \tfrac{m_0}{C_0}\big)\theta\Big]\right\}, } $$
\textcolor{orange}{the kernel of a Gaussian. Matching the} $\omark{\theta^2}$ \textcolor{orange}{and} $\omark{\theta}$ \textcolor{orange}{coefficients gives} $\omark{\theta \mid y_{1:t} \sim \mathcal{N}(m_t, C_t)}$ \textcolor{orange}{with (book 1.2):}
$$ \omark{ \boxed{\; C_t = \Big(\tfrac{t}{\sigma^2} + \tfrac{1}{C_0}\Big)^{-1} = \frac{\sigma^2 C_0}{\sigma^2 + t C_0}, \qquad m_t = C_t\Big(\tfrac{t\bar y}{\sigma^2} + \tfrac{m_0}{C_0}\Big) = \frac{C_0}{C_0 + \sigma^2/t}\,\bar y + \frac{\sigma^2/t}{C_0 + \sigma^2/t}\,m_0. \;} } $$
\textcolor{orange}{Posterior precision} $\omark{1/C_t = t/\sigma^2 + 1/C_0}$ \textcolor{orange}{is the sum of the data precision} $\omark{t/\sigma^2}$ \textcolor{orange}{and prior precision} $\omark{1/C_0}$\textcolor{orange}{; the mean} $\omark{m_t}$ \textcolor{orange}{is the precision-weighted average of the sample mean} $\omark{\bar y}$ \textcolor{orange}{and the prior guess} $\omark{m_0}$\textcolor{orange}{.}

\medskip

\textcolor{orange}{\emph{(Sept 2025 Q8b) Numbers:}} $\omark{n = 20}$\textcolor{orange}{,} $\omark{\bar y = 4}$\textcolor{orange}{,} $\omark{\sigma^2 = 1}$\textcolor{orange}{:}
$$ \omark{ C_{20} = \Big(20 + \tfrac{1}{C_0}\Big)^{-1}, \qquad m_{20} = \frac{C_0}{C_0 + 1/20}\cdot 4 \;+\; \frac{1/20}{C_0 + 1/20}\, m_0. } $$
\textcolor{orange}{Under a vague prior} $\omark{C_0 \to \infty}$ \textcolor{orange}{the prior washes out:} $\omark{m_{20} \to \bar y = 4}$ \textcolor{orange}{and} $\omark{C_{20} \to \sigma^2/n = 1/20 = 0.05}$\textcolor{orange}{.}

\medskip

\textcolor{orange}{\emph{Recursive (Kalman) form} (book 1.3): each new} $\omark{y_t}$ \textcolor{orange}{updates the previous posterior} $\omark{\mathcal{N}(m_{t-1}, C_{t-1})}$ \textcolor{orange}{(now playing the role of prior):}
$$ \omark{ m_t = m_{t-1} + \frac{C_{t-1}}{C_{t-1}+\sigma^2}\,(y_t - m_{t-1}), \qquad C_t = \Big(\tfrac1{\sigma^2}+\tfrac1{C_{t-1}}\Big)^{-1} = \frac{\sigma^2 C_{t-1}}{\sigma^2 + C_{t-1}}. } $$
\textcolor{orange}{This is exactly the Kalman filter with} $\omark{a_t = m_{t-1}}$\textcolor{orange}{,} $\omark{R_t = C_{t-1} + W = C_{t-1}}$ \textcolor{orange}{(since} $\omark{W = 0}$\textcolor{orange}{),} $\omark{Q_t = C_{t-1} + \sigma^2}$ \textcolor{orange}{and gain} $\omark{A_t = C_{t-1}/(C_{t-1}+\sigma^2)}$\textcolor{orange}{; the correction is the forecast error} $\omark{y_t - m_{t-1}}$ \textcolor{orange}{weighted by the gain (June 2022 Q7 asks precisely for} $\omark{\theta_n \mid y_{1:n}}$\textcolor{orange}{).}

\medskip

\textcolor{orange}{\emph{Fixed-}}$\omark{\theta}$ \textcolor{orange}{limit: iterating the precision recursion gives} $\omark{1/C_t = t/\sigma^2 + 1/C_0 \to \infty}$\textcolor{orange}{, hence} $\omark{C_t \to 0}$ \textcolor{orange}{--- with a} \emph{constant} \textcolor{orange}{target the posterior concentrates on the true} $\omark{\theta}$\textcolor{orange}{. The general random walk plus noise case} $\omark{W > 0}$ \textcolor{orange}{(where instead} $\omark{C_t \to C^* > 0}$\textcolor{orange}{) is exam question May 2026 Q4 / May 2025 Q5c and is derived in the sibling convergence node --- not repeated here.}

\smallskip

\textcolor{orange}{\emph{Cross-ref:} the general matrix version of this update is derived in the sibling node ``Filter update: derivation of} $\omark{m_t}$\textcolor{orange}{,} $\omark{C_t}$ \textcolor{orange}{(Proof A)''; here} $\omark{F_t = 1}$\textcolor{orange}{,} $\omark{G_t = 1}$\textcolor{orange}{,} $\omark{W = 0}$\textcolor{orange}{,} $\omark{V = \sigma^2}$ \textcolor{orange}{specialise it to the scalar constant-mean case.}

\end{keydef}

\begin{keydef}
\textbf{\textcolor{red}{Why standard ARMA models require stationarity.}}

\fcnum{20} An ARMA model imposes a "predefined" structure constrained by constant parameters.  Under these conditions, the resulting process has ==time-invariant statistical properties==.  
A DLM is a model more prone to flexibility, capable of capturing non-stationarities such as trends, evolving seasonal patterns, or time-varying volatility.
\end{keydef}

\textbf{\textcolor{red}{SMOOTHING}}

\begin{keydef}
\fcnum{31} 
$\bullet$ \emph{\textcolor{orange}{Marginal} smoothing:} $\boxed{\,\pi(\theta_t \mid y_{1:T}),\quad t < T\,}$. \textcolor{orange}{\emph{Joint smoothing:}} $\omark{\pi(\theta_{0:T} \mid y_{1:T})}$ \textcolor{orange}{--- the full latent path given all data.}

\textcolor{orange}{\emph{Ingredients (stored on the forward KF pass):}} $\omark{\theta_t \mid y_{1:t} \sim \mathcal{N}(m_t, C_t)}$ \textcolor{orange}{(filter) and} $\omark{\theta_{t+1} \mid y_{1:t} \sim \mathcal{N}(a_{t+1}, R_{t+1})}$ \textcolor{orange}{(one-step-ahead predictive), with} $\omark{a_{t+1} = G_{t+1} m_t}$\textcolor{orange}{,} $\omark{R_{t+1} = G_{t+1} C_t G_{t+1}^\top + W_{t+1}}$\textcolor{orange}{.}

\textbf{\textcolor{red}{Kalman smoother --- one backward pass, two possible outputs.}}

\textbf{(A) Analytical marginals} $\theta_t \mid y_{1:T} \sim \mathcal{N}(s_t, S_t)$ (Prop.\ 2.4, p.\ 61)\textcolor{orange}{, initialized at} $\omark{\boxed{s_T = m_T,\; S_T = C_T}}$ \textcolor{orange}{and run backward} $\omark{t = T-1, T-2, \dots, 0}$:
$$ s_t \;=\; m_t + J_t\, (s_{t+1} - a_{t+1}), \qquad S_t \;=\; C_t - J_t\, (R_{t+1} - S_{t+1})\, J_t^\top. $$
\emph{The smoother gain (shared by both outputs):}
$$ \boxed{\; J_t \;=\; C_t\, G_{t+1}^\top\, R_{t+1}^{-1}. \;} $$

\textbf{\textcolor{orange}{(B) Backward sampling (joint smoothing / FFBS):}} \textcolor{orange}{justification --- the joint smoothing law factorizes backward (eq.\ 4.21, p.\ 161):}
$$ \omark{\pi(\theta_{0:T} \mid y_{1:T}) \;=\; \prod_{t=0}^{T} \pi(\theta_t \mid \theta_{t+1:T},\, y_{1:T})} $$
\textcolor{orange}{whose last factor is simply the filtering distribution} $\omark{\pi(\theta_T \mid y_{1:T}) = \mathcal{N}(m_T, C_T)}$ \textcolor{orange}{and whose generic factor reduces to the backward kernel of step (iii):} $\omark{\pi(\theta_t \mid \theta_{t+1:T},\, y_{1:T}) = \pi(\theta_t \mid \theta_{t+1},\, y_{1:t})}$\textcolor{orange}{. So sampling each factor in turn yields a draw of the whole path: draw} $\omark{\theta_T \sim \mathcal{N}(m_T, C_T)}$\textcolor{orange}{, then for} $\omark{t = T-1, \dots, 0}$ \textcolor{orange}{draw}
$$ \omark{\theta_t \mid \theta_{t+1},\, y_{1:T} \;\sim\; \mathcal{N}\!\bigl(\, m_t + J_t(\theta_{t+1} - a_{t+1}),\;\; C_t - J_t\, G_{t+1}\, C_t \,\bigr),} $$
\textcolor{orange}{and the resulting path is a draw from the joint} $\omark{\pi(\theta_{0:T} \mid y_{1:T})}$ \textcolor{orange}{(Algorithm 4.1, p.\ 162).}

\textbf{\textcolor{orange}{Backward-Markov property by d-separation (May 2023 Q5 / Sep 2025 Q7(c); Step 1 of the RTS proof).}}

\textcolor{orange}{\emph{Claim:}} $\omark{\theta_t \perp\!\!\!\perp (Y_{t+1},\dots,Y_T) \mid \theta_{t+1}}$\textcolor{orange}{.}

\textcolor{orange}{\emph{Proof (2--3 lines).} The DLM DAG is}
$$ \omark{\theta_0 \to \theta_1 \to \cdots \to \theta_t \to \theta_{t+1} \to \cdots \to \theta_T, \qquad \theta_s \to Y_s \;\; (s = 1, \dots, T),} $$
\textcolor{orange}{i.e.\ the states form a Markov chain and each observation $Y_s$ is a child of its contemporaneous state $\theta_s$ only.} \textcolor{orange}{Every path from $\theta_t$ to any $Y_s$ with $s \ge t+1$ must travel along the state chain, hence passes through $\theta_{t+1}$, which sits on it as a \emph{serial (chain) node}, not a collider.} \textcolor{orange}{Conditioning on $\theta_{t+1}$ therefore blocks every such path: the two sets are d-separated by} $\omark{\{\theta_{t+1}\}}$\textcolor{orange}{, and d-separation implies conditional independence for a joint law factorizing along the DAG, so} $\omark{\theta_t \perp\!\!\!\perp Y_{t+1:T} \mid \theta_{t+1}}$\textcolor{orange}{.} $\omark{\square}$

\textcolor{orange}{Equivalently} $\omark{\pi(\theta_t \mid \theta_{t+1},\, y_{1:T}) = \pi(\theta_t \mid \theta_{t+1},\, y_{1:t})}$ \textcolor{orange}{--- given $\theta_{t+1}$, the future data add no information about $\theta_t$: exactly fact (1) used in step (i) of the RTS proof below.}

\textbf{\textcolor{red}{Proof of the analytical-marginal formulas (RTS).}}

\textcolor{orange}{\emph{Backward induction:} assume} $\omark{\theta_{t+1} \mid y_{1:T} \sim \mathcal{N}(s_{t+1}, S_{t+1})}$ \textcolor{orange}{(true at $\omark{t = T}$ with $\omark{s_T = m_T,\, S_T = C_T}$).} \textcolor{orange}{Since all states and observations are jointly Gaussian,} $\omark{\theta_t \mid y_{1:T}}$ \textcolor{orange}{is Gaussian too, so it suffices to compute its mean and variance.}

\emph{(i) Marginalisation + chain rule.}
$$ \pi(\theta_t \mid y_{1:T})  \; \underbrace{=}_{\text{ Marginalisation + chain rule}}\; \int \underbrace{\pi(\theta_t \mid \theta_{t+1},\, y_{1:T})}_{\pi(\theta_t \mid \theta_{t+1},\, y_{1:t}) \text{ by (1)}} \, \pi(\theta_{t+1} \mid y_{1:T})\, d\theta_{t+1} $$
(1) \textcolor{orange}{By $\omark{d}$-separation on the DLM DAG:} Given $\theta_{t+1}$, the future observations $y_{t+1:T}$ add no information about $\theta_t$\textcolor{orange}{ --- every path from} $\omark{y_{t+1:T}}$ \textcolor{orange}{to $\omark{\theta_t}$ passes through the serial node} $\omark{\theta_{t+1}}$\textcolor{orange}{.}


\emph{(ii) Compute the backward kernel $\pi(\theta_t \mid \theta_{t+1}, y_{1:t})$ via Bayes (likelihood $\times$ prior):} 
$$ \pi(\theta_t \mid \theta_{t+1},\, y_{1:t}) \;\propto\; \overbrace{\pi(\theta_{t+1} \mid \theta_t,\, y_{1:t})}^{\text{likelihood, simplify:} \pi(\theta_{t+1} \mid \theta_t)}\, \overbrace{\pi(\theta_t \mid y_{1:t})}^{\text{prior}} $$
\textcolor{orange}{The simplification of the likelihood uses the companion fact to (1):} $\omark{\theta_{t+1} \perp\!\!\!\perp Y_{1:t} \mid \theta_t}$\textcolor{orange}{; both conditional independencies are named in the proof of Prop.\ 2.3 (p.\ 60), and the likelihood is then expressed by the state equation (2.4c).} \textcolor{orange}{Full d-separation proof of this fact: node \emph{SSM filtering and prediction}.}

 Both factors are Gaussian (read off the filter and the model):
- From the state equation\textcolor{orange}{: Gaussian, with mean} $G_{t+1}\theta_t$ fixed once you know $\theta_t$. $$ \pi(\theta_{t+1} \mid \theta_t) = \mathcal{N}(G_{t+1}\theta_t,\, W_{t+1})$$
- This you already know: 
$$\pi(\theta_t \mid y_{1:t}) = \mathcal{N}(m_t, C_t). $$
(iii) By Gaussian conditioning\textcolor{orange}{: given} $\omark{y_{1:t}}$\textcolor{orange}{, the pair} $\omark{(\theta_t, \theta_{t+1})}$ \textcolor{orange}{is jointly Gaussian with marginals} $\omark{\mathcal{N}(m_t, C_t)}$\textcolor{orange}{,} $\omark{\mathcal{N}(a_{t+1}, R_{t+1})}$ \textcolor{orange}{and cross-covariance}
$$ \omark{\mathrm{Cov}(\theta_t,\, \theta_{t+1} \mid y_{1:t}) \;=\; \mathrm{Cov}(\theta_t,\, G_{t+1}\theta_t + w_{t+1} \mid y_{1:t}) \;=\; C_t\, G_{t+1}^\top} $$
\textcolor{orange}{(since} $\omark{w_{t+1} \perp (\theta_t,\, y_{1:t})}$\textcolor{orange}{). Conditioning within this Gaussian pair --- regression coefficient} $\omark{\mathrm{Cov} \cdot \mathrm{Var}^{-1}}$ \textcolor{orange}{---} with $J_t = C_t\, G_{t+1}^\top\, R_{t+1}^{-1}$:
$$ \theta_t \mid \theta_{t+1},\, y_{1:t} \;\sim\; \mathcal{N}\!\bigl(\, m_t + J_t(\theta_{t+1} - a_{t+1}),\;\; C_t - J_t\, G_{t+1}\, C_t \,\bigr). $$

\emph{(iv) Take expectation and variance of the integral (tower rules).}

\emph{Mean.} $\;s_t = E[\theta_t \mid y_{1:T}] = E\bigl[E[\theta_t \mid \theta_{t+1}, y_{1:t}] \mid y_{1:T}\bigr] = E\bigl[m_t + J_t(\theta_{t+1} - a_{t+1}) \mid y_{1:T}\bigr]$
$$ \;=\; m_t + J_t\, (s_{t+1} - a_{t+1}), $$
using \textcolor{orange}{the induction hypothesis} $E[\theta_{t+1} \mid y_{1:T}] = s_{t+1}$. \quad $\checkmark$

\emph{Variance.} Law of total variance:
$$ S_t \;=\; E\bigl[\mathrm{Var}(\theta_t \mid \theta_{t+1}, y_{1:t}) \mid y_{1:T}\bigr] + \mathrm{Var}\bigl(E[\theta_t \mid \theta_{t+1}, y_{1:t}] \mid y_{1:T}\bigr). $$
The first term is constant (the conditional variance doesn't depend on $\theta_{t+1}$): $C_t - J_t G_{t+1} C_t$. The second is $\mathrm{Var}(J_t \theta_{t+1} \mid y_{1:T}) = J_t S_{t+1} J_t^\top$ \textcolor{orange}{by the induction hypothesis}. So
$$ S_t \;=\; C_t - J_t\, G_{t+1}\, C_t + J_t\, S_{t+1}\, J_t^\top. $$
Use $J_t G_{t+1} C_t = J_t R_{t+1} J_t^\top$ (since $J_t = C_t G_{t+1}^\top R_{t+1}^{-1}$ $\Rightarrow$ $J_t R_{t+1} = C_t G_{t+1}^\top$ $\Rightarrow$ $J_t R_{t+1} J_t^\top = C_t G_{t+1}^\top J_t^\top = J_t G_{t+1} C_t$\textcolor{orange}{, using symmetry of $\omark{C_t}$,} $\omark{R_{t+1}}$) to rewrite:
$$ S_t \;=\; C_t - J_t\, (R_{t+1} - S_{t+1})\, J_t^\top. \quad \checkmark $$
\textcolor{orange}{Backward induction from $\omark{t = T-1}$ down to $\omark{t = 0}$ completes the proof. $\omark{\square}$}
\end{keydef}

