\textbf{Gaussian predictive distribution $\Longrightarrow$ Gaussian innovation $\Longrightarrow$ standardized innovation}
\$$2mm]

\[
\boxed{
Y_t\mid y_{1:t-1}\sim\mathcal N(f_t,Q_t)
}
\quad\Longrightarrow\quad
\boxed{
e_t=Y_t-f_t
\;\Bigm|\;
y_{1:t-1}
\sim
