\textbf{(1) Expected value: $\mathbb{E}(e_t)=0$}
\$$2mm]

\[
\mathbb{E}(e_t)
=
\mathbb{E}(Y_t-f_t)
\overset{\text{tower property}}{=}
\mathbb{E}\!\left[
\mathbb{E}(Y_t-f_t\mid y_{1:t-1})
\right]
=
\mathbb{E}\!\left[
\underbrace{\mathbb{E}(Y_t\mid y_{1:t-1})}_{=\,f_t\text{ by definition}}
-
\underbrace{\mathbb{E}(f_t\mid y_{1:t-1})}_{=\,f_t}
\right]
=
\mathbb{E}[f_t-f_t]
=
0.
$$
\\
\hline

\textbf{(2) Uncorrelated across time:
$\mathrm{Cov}(e_t,e_s)=0$ for $s<t$}
\$$2mm]

Since $s<t$, $e_s$ is past-measurable:
\[
e_s=g(y_{1:t-1}).
$$

Therefore,
$$
\mathrm{Cov}(e_t,e_s)
=
\underbrace{
\mathbb{E}(e_t e_s)
-
\mathbb{E}(e_t)\mathbb{E}(e_s)
}_{\text{definition of covariance}}
=
\underbrace{
\mathbb{E}(e_t e_s)
}_{\mathbb{E}(e_t)=\mathbb{E}(e_s)=0}
\overset{\text{tower property}}{=}
\mathbb{E}\!\left[
\underbrace{
\mathbb{E}(e_t e_s\mid y_{1:t-1})
}_{e_s\text{ pulls out, past-measurable}}
\right]
=
\mathbb{E}\!\left[
e_s
\underbrace{
\mathbb{E}(e_t\mid y_{1:t-1})
}_{=\,0}
\right]
=
0.
$$
\\
