\begin{keydef}

\textbf{\textcolor{red}{Filter/update: derivation of $m_t$ and $C_t$ (Bayes + Gaussian kernel matching).}}

\medskip

\textbf{Step 1 --- Bayes' rule.}

Since $y_{1:t}=(y_{1:t-1},y_t)$,
$$
p(\theta_t\mid y_{1:t})
=
\frac{
p(y_t\mid\theta_t,y_{1:t-1})\,
p(\theta_t\mid y_{1:t-1})
}{
p(y_t\mid y_{1:t-1})
}.
$$

By emission conditional independence, $Y_t\perp\!\!\!\perp y_{1:t-1}\mid\theta_t$, so $p(y_t\mid\theta_t,y_{1:t-1})=p(y_t\mid\theta_t)$. Since the denominator does not depend on $\theta_t$,
$$
\boxed{
p(\theta_t\mid y_{1:t})
\propto
\underbrace{p(y_t\mid\theta_t)}_{\text{likelihood}}\,
\underbrace{p(\theta_t\mid y_{1:t-1})}_{\text{predicted prior}}.
}
$$

\medskip

\textbf{Step 2 --- Predicted prior kernel.}

\textcolor{orange}{This proof takes the one-step-ahead \emph{prediction} step} $\omark{\theta_t\mid y_{1:t-1}\sim\mathcal N_p(a_t,R_t)}$ \textcolor{orange}{as given, not derived. Exam June 2025 Q3c asks to derive and prove} $\omark{\theta_t\mid y_{1:t}}$ \textcolor{orange}{starting from} $\omark{\theta_{t-1}\mid y_{1:t-1}\sim\mathcal N_p(m_{t-1},C_{t-1})}$\textcolor{orange}{, and May 2021 Q5c asks to ``prove the first step''; both require deriving} $\omark{a_t=G_tm_{t-1}}$\textcolor{orange}{,} $\omark{R_t=G_tC_{t-1}G_t^\top+W_t}$ \textcolor{orange}{(book Prop 2.2(i), via the tower rule and the law of total variance) --- carried out in the sibling node \emph{SSM filtering and prediction}.}

Since $\theta_t\mid y_{1:t-1}\sim\mathcal N_p(a_t,R_t)$,
$$
p(\theta_t\mid y_{1:t-1})
\propto
\exp\left\{
-\tfrac12
\left[
\theta_t^\top R_t^{-1}\theta_t
-2\theta_t^\top R_t^{-1}a_t
\right]
\right\}.
$$

\medskip

\textbf{Step 3 --- Likelihood kernel.}

Since $Y_t\mid\theta_t\sim\mathcal N_q(F_t\theta_t,V_t)$,
$$
p(y_t\mid\theta_t)
\propto
\exp\left\{
-\tfrac12
\left[
\theta_t^\top F_t^\top V_t^{-1}F_t\theta_t
-2\theta_t^\top F_t^\top V_t^{-1}y_t
\right]
\right\}.
$$

\medskip

\textbf{Step 4 --- Multiply prior and likelihood.}
$$
\begin{aligned}
p(\theta_t\mid y_{1:t})
\propto
\exp\Bigg\{
-\tfrac12
\Big[
&
\theta_t^\top
\left(
R_t^{-1}+F_t^\top V_t^{-1}F_t
\right)
\theta_t
\\
&-2\theta_t^\top
\left(
R_t^{-1}a_t+F_t^\top V_t^{-1}y_t
\right)
\Big]
\Bigg\}.
\end{aligned}
$$

\medskip

\textbf{Step 5 --- Match with a Gaussian posterior.}

If $\theta_t\mid y_{1:t}\sim\mathcal N_p(m_t,C_t)$, matching coefficients gives the \textbf{precision form}:
$$
\boxed{
C_t^{-1}=R_t^{-1}+F_t^\top V_t^{-1}F_t,
\qquad
m_t=C_t\left(R_t^{-1}a_t+F_t^\top V_t^{-1}y_t\right).
}
$$

\medskip

\textbf{Step 6 --- Rewrite $C_t$ in Kalman form.}

With $Q_t=F_tR_tF_t^\top+V_t$, the Woodbury identity gives
$$
C_t
=\left(R_t^{-1}+F_t^\top V_t^{-1}F_t\right)^{-1}
=\boxed{R_t-R_tF_t^\top Q_t^{-1}F_tR_t.}
$$
Define the \textbf{Kalman gain} $K_t=R_tF_t^\top Q_t^{-1}$. Then
$$
\boxed{
C_t=R_t-K_tF_tR_t=R_t-K_tQ_tK_t^\top.
}
$$

\medskip

\textbf{\textcolor{orange}{Book route (Prop 2.2(iii), DLMwR p.54--55).}} \textcolor{orange}{The book reaches the same} $\omark{m_t,C_t}$ \textcolor{orange}{without precision-matching or Woodbury: it observes that updating the conjugate Gaussian prior} $\omark{\theta_t\mid y_{1:t-1}\sim\mathcal N_p(a_t,R_t)}$ \textcolor{orange}{with the linear-Gaussian observation} $\omark{Y_t=F_t\theta_t+v_t,\ v_t\sim\mathcal N_q(0,V_t)}$ \textcolor{orange}{is exactly the Bayesian normal linear model of Section 1.5, so it reads off} $\omark{m_t=a_t+R_tF_t^\top Q_t^{-1}(y_t-F_ta_t)}$ \textcolor{orange}{directly from eq.\ (1.10) and} $\omark{C_t=R_t-R_tF_t^\top Q_t^{-1}F_tR_t}$ \textcolor{orange}{from eq.\ (1.9). Steps 5--6 above are the equivalent precision/Woodbury route to that same result.}

\medskip

\textbf{Step 7 --- Rewrite $m_t$ in Kalman form.}

From the identities above, $C_tF_t^\top V_t^{-1}=R_tF_t^\top Q_t^{-1}=K_t$, and multiplying $C_t^{-1}=R_t^{-1}+F_t^\top V_t^{-1}F_t$ by $C_t$ gives $C_tR_t^{-1}=I-K_tF_t$. Hence
$$
\begin{aligned}
m_t
&=C_t\left(R_t^{-1}a_t+F_t^\top V_t^{-1}y_t\right)
=C_tR_t^{-1}a_t+C_tF_t^\top V_t^{-1}y_t
\\
&=(I-K_tF_t)a_t+K_ty_t
=a_t+K_t(y_t-F_ta_t).
\end{aligned}
$$
With $f_t=F_ta_t$ and $e_t=y_t-f_t$,
$$
\boxed{
\begin{aligned}
K_t &= R_tF_t^\top Q_t^{-1},\\
m_t &= a_t+K_t(y_t-f_t)=a_t+K_te_t,\\
C_t &= R_t-R_tF_t^\top Q_t^{-1}F_tR_t=R_t-K_tQ_tK_t^\top.
\end{aligned}
}
$$

\medskip

\textbf{Interpretation.}

$$
\boxed{
\underbrace{\theta_t\mid y_{1:t-1}\sim\mathcal N_p(a_t,R_t)}_{\text{prediction before seeing }y_t}
\;\xrightarrow{\;\text{observe }y_t\;}\;
\underbrace{\theta_t\mid y_{1:t}\sim\mathcal N_p(m_t,C_t)}_{\text{updated/filter distribution}}
}
$$
via
$$
\boxed{
\text{predicted prior}\times\text{likelihood}
\xrightarrow{\text{Bayes}}
\text{posterior}.
}
$$
Finally,
$$
\boxed{
\underbrace{m_t}_{\text{updated state}}
=\underbrace{a_t}_{\text{predicted state}}
+\underbrace{K_t}_{\text{strength of correction}}
\underbrace{(y_t-f_t)}_{\text{forecast error}}.
}
$$

\end{keydef}

\textbf{\textcolor{red}{MODEL CHECKING --- forecast errors / innovations.}}

\begin{keydef}

\fcnum{29} 
recall
$$\boxed{
f_t = \mathbb{E}\!\left(Y_t \mid y_{1:t-1}\right)
}
\quad \Longrightarrow \quad
\boxed{
e_t = y_t - f_t
}
\quad \Longrightarrow \quad
\boxed{
\text{if the model is correct} \quad
e_t \sim \mathcal{N}(0,Q_t)
\;\; \text{indep over t}
}
\quad \Longrightarrow \quad
\boxed{
\tilde e_t
= \frac{e_t}{\sqrt{Q_t}}
