$$
Q_t
=
\mathrm{Var}(Y_t \mid y_{1:t-1})
=
\mathrm{Var}(e_t \mid y_{1:t-1})
$$
So this is the predicted conditional noise (the nosie the model expected), then $e_t$ is the actual noise. 

\textcolor{red}{Prove $\tilde e_t$ is a Gaussian white noise: iid $\mathcal{N}(0,\, 1)$.}
\textbf{(1) Zero mean: $\mathbb{E}(e_t) = 0$.}
$$ \mathbb{E}(e_t) \;=\; \mathbb{E}(Y_t - f_t) \;\overset{\text{tower ppt}}{=}\; \mathbb{E}\!\bigl[\, \mathbb{E}\bigl(Y_t - f_t \mid y_{1:t-1}\bigr)\,\bigr] \;=\; \mathbb{E}\!\bigl[\, \underbrace{\mathbb{E}(Y_t \mid y_{1:t-1})}_{=\, f_t \text{ by definition}} \;-\; \underbrace{\mathbb{E}(f_t \mid y_{1:t-1})}_{= f_t } \;=\; \mathbb{E}[\, f_t - f_t\,] \;=\; 0. $$

\textbf{(2) Uncorrelated across time: $\mathrm{Cov}(e_t, e_s) = 0$ for $s < t$.}

i) \emph{$e_s$ is past-measurable}: $e_s \;=\; g(y_{1:t-1})$

ii) \emph{Apply LIE.}
$$
\mathrm{Cov}(e_t,e_s)
\;=\;
\underbrace{
\mathbb{E}(e_t e_s)
-
\mathbb{E}(e_t)\mathbb{E}(e_s)
}_{\text{definition of covariance}}
\;=\;
\underbrace{
\mathbb{E}(e_t e_s)
}_{\mathbb{E}(e_t)=\mathbb{E}(e_s)=0\text{ by (i)}}
\;\overset{\text{LIE}}{=}\;
\mathbb{E}\!\bigl[\,
\underbrace{
\mathbb{E}(e_t e_s \mid y_{1:t-1})
}_{e_s \text{ pulls out, past-meas.}}
\,\bigr]
\;=\;
\mathbb{E}\!\bigl[\,
e_s \cdot
\underbrace{
\mathbb{E}(e_t \mid y_{1:t-1})
}_{=\,0\text{ as in (i)}}
\,\bigr]
\;=\;0.
$$

\textbf{(3) Variance --- needs the \emph{law of total variance} (LTV).}

$$ \mathrm{Var}(e_t) \;\overset{\text{LTV}}{=}\; \mathbb{E}\!\bigl[\, \underbrace{\mathrm{Var}(e_t \mid y_{1:t-1})}_{=\, Q_t,\ \text{see below}}\,\bigr] \;+\; \mathrm{Var}\!\bigl[\, \underbrace{\mathbb{E}(e_t \mid y_{1:t-1})}_{=\, 0 \text{ as in (i)}}\,\bigr] \;=\; \mathbb{E}[Q_t] \;+\; \mathrm{Var}[0] \;=\; \mathbb{E}[Q_t]. $$

\emph{Why $\mathrm{Var}(e_t \mid y_{1:t-1}) = Q_t$?}
$$ \mathrm{Var}(e_t \mid y_{1:t-1}) \;=\; \mathrm{Var}(Y_t - f_t \mid y_{1:t-1}) \;\overset{(\star)}{=}\; \mathrm{Var}(Y_t \mid y_{1:t-1}) \;=\; Q_t. $$
$(\star)$: $f_t$ is a constant given that conditioning.

\textbf{(4) Put it all together --- standardise.}

\emph{Standardise.}

$$\boxed{
e_t \mid y_{1:t-1} \sim \mathcal{N}(0,Q_t)
}
$$

$$$$

$$
\Longrightarrow
\boxed{
\tilde e_t
=
\frac{e_t}{\sqrt{Q_t}}
\;\Bigm|\;
y_{1:t-1}
\sim
\mathcal{N}(0,1)
}
$$

\emph{Marginalise.} This conditional law does \emph{not depend on} $y_{1:t-1}$, so the marginal is the same: $\tilde e_t \sim \mathcal{N}(0,1)$. Idea: if $X \mid Y$ has the same distribution for every $Y$, then $X$ is independent of $Y$, and     marginally $X$ just has that distribution. The conditioning is doing no work.

\emph{Independence.} The whole $\{e_t\}$ process is jointly Gaussian, and by (ii) they are pairwise uncorrelated. For jointly Gaussian variables, uncorrelated $\Leftrightarrow$ independent. Standardising preserves this.

\emph{Conclusion.} $\{\tilde e_t\}$ is iid $\mathcal{N}(0,1)$. $\square$
\end{keydef}


Useful plots to test errors behave as e_t \sim \mathcal{N}(0,Q_t): 
$\bullet$ \emph{Normality:} Q--Q plot of $\{\tilde e_t\}$ against $\mathcal{N}(0,1)$; Shapiro--Wilk.
$\bullet$ \emph{No autocorrelation:} ACF/PACF of $\{\tilde e_t\}$ should look like white noise; Ljung--Box test.
$\bullet$ \emph{Variance stable:} time plot of $\tilde e_t$ --- no heteroskedasticity / outliers / change-points.

If any of these fails, the model is mis-specified (wrong $G, F, V, W$, missing component, wrong noise distribution, $\dots$).

\textbf{\textcolor{red}{ERGODIC PROPERTIES OF A MARKOV CHAIN}}

In general the random variables $Y_t$ are \emph{not} identically distributed — the distribution of $Y_t$ varies with $t$, hence the process $(Y_t)_{t \ge 0}$ is not (strictly) stationary. We want to study its \textbf{asymptotic behaviour} (as $t \to \infty$).


\begin{keydef}
\fcnum{16} Let $(Y_t)$ be an \textbf{irreducible} and \textbf{aperiodic} Markov chain (discrete time) with finite state space $\mathcal{Y} = \{1, \dots, M\}$. Then:

\textbf{(1)} $$ \lim_{t \to \infty} P(Y_t = k \mid Y_0 = j) = \underbrace{p^*(k)}_{\text{Limit distribution}} > 0, \qquad \forall j, k \in \mathcal{Y}, \qquad \sum_{k \in \mathcal{Y}} p^*(k) = 1. $$
now how this means the limit does not depend on the starting condition!
\textbf{(2)}$$ \underbrace{p^*(k)}_{\text{prob.\ of being in } k \text{ (next step)}} \;=\; \sum_{i \in \mathcal{Y}} \underbrace{p^*(i)}_{\text{prob.\ of being in } i \text{ (current step)}} \cdot \underbrace{p_{i,k}}_{\text{transition } i \to k}, \qquad \forall k \in \mathcal{Y}. $$
In row-vector form: $\boldsymbol{p}^* = \boldsymbol{p}^* \, \mathbf{P}$ rather than $\boldsymbol{\pi_{t+1}}^* = \boldsymbol{\pi_t}^* \, \mathbf{P}$ it is a fixed point!
\end{keydef}









*remark: we do not use f ( a < y < b) because up to now the state space is finite

\begin{keydef}
\fcnum{5a} \textbf{A stochastic process} $(Y_t)_{t \in T}$ is a sequence of random vectors (a multidimensional random variable) indexed by $t \in T$.
\end{keydef} 

\begin{keydef}
\fcnum{5b} \textbf{A time series} is a stochastic process $(Y_t)_{t \in T}$ with $Y_t \in \mathcal{Y}$. The data $(y_1, \dots, y_t)$ are the initial trait (i.e.\ a \emph{finite realization}) of the stochastic process.
\end{keydef} 




Note:
- This is not a single random variable, nor a single random vector. It is a \emph{sequence} of random variables / vectors! E.g.\ the sequence of outcomes of a repeated game.  
- is 'a time series is a sequence of observations taken over time' a good definition? No, superficial

\textbf{\textcolor{red}{EXAMPLE 0 --- White noise (the simplest building block).}}

\begin{keydef}
\fcnum{9} A sequece of independent identiclal distirbuted zero mean normal random variables.
\[ Y_t \;\underbrace{\sim}_{iid}\; \mathcal{N}(0, \sigma^2), \qquad t = 1, 2, \dots \]
\emph{No temporal dependence at all --- knowing $Y_{t-1}$ tells you nothing about $Y_t$.}
\[ E[Y_t] \;=\; 0 \qquad \forall\, t. \]
\[ \mathrm{Var}(Y_t) \;=\; \sigma^2 \qquad \forall\, t. \]
\emph{Variance is constant in $t$ --- nothing grows, nothing decays.}
\emph{Autocovariance.} By independence, $\mathrm{Cov}(Y_t, Y_s) = 0$ whenever $t \neq s$:
\[ \gamma(h) \;:=\; \mathrm{Cov}(Y_t, Y_{t+h}) \;=\; \begin{cases} \sigma^2 & h = 0, \\ 0 & h \neq 0. \end{cases} \]
Depends only on the lag $h$ (and only the zero lag is non-zero). \quad $\checkmark$

\emph{Autocorrelation.} $\rho(0) = 1$, $\rho(h) = 0$ for $h \neq 0$. \emph{The correlogram is a single spike at lag 0.}

\textbf{Stationarity verdict.} Constant mean $+$ constant variance $+$ autocovariance depending only on lag $\Rightarrow$ \textbf{weakly stationary} (and \emph{strictly} stationary too, by the iid assumption). \quad $\checkmark\checkmark$
\end{keydef}

\textbf{\textcolor{red}{MOST TRIVIAL EXAMPLE OF STOCH.\ PROCESS}}

\begin{keydef}
\textbf{\fcnum{13b} IID stochastic processes}
Say $Y_t,\ t \in \{0, 1, \dots, n\}$ are independent. If, additionally, $Y_t$ have a common distribution (i.i.d.) with $p$:
$$ p(y_{0:n}) \;=\; p(y_0)\, p(y_1) \cdots p(y_n) \;=\; \prod_{t=0}^{n} p(y_t). $$
\end{keydef}

\emph{Example} Independent trials $Y_t \stackrel{\text{iid}}{\sim}$ Bernoulli$(p)$.
\emph{If you forced it into a "transition" table} (even though iid has no real Markov dependence --- the rows are identical, which is the giveaway that the past is irrelevant):
$$ \begin{array}{c|cc} t-1 \backslash t & 0 & 1 \\ \hline 0 & 1-p & p \\ 1 & 1-p & p \end{array} $$
\emph{The two rows being equal} $\Leftrightarrow$ $P(Y_t = j \mid Y_{t-1} = i) = P(Y_t = j)$, i.e.\ no dependence on the past --- which is exactly the iid (memoryless) property.

\begin{keydef}
\textbf{\fcnum{13c} Independent (not necessarily identically distributed) stochastic processes}
If only indep.\ (not necessarily identically distrib.):
$$ p(y_{0:n}) \;=\; p_0(y_0)\, p_1(y_1) \cdots p_n(y_n) \;=\; \prod_{t=0}^{n} p_t(y_t). $$
\end{keydef}


Both assume independence: irrealistic for time series

\begin{keydef}
\textbf{\fcnum{13d} Full dependence (general chain rule).}
$$ p(y_{0:n}) \;=\; p_0(y_0)\, p_1(y_1 \mid y_0)\, p_2(y_2 \mid y_0, y_1) \cdots p_n(y_n \mid y_{0:n-1}) \;=\; p_0(y_0) \prod_{t=1}^{n} p_t(y_t \mid y_{0:t-1}). $$
\end{keydef}

\begin{keydef}
\fcnum{21b} \textbf{General DLM (linear Gaussian SSM). <--- is the DLM!!! }

\emph{State.} $\theta_t = (\theta_{1t},\theta_{2t}...\theta_{pt} )^\top \in \mathbb{R}^p$ (p processes!). Initial: $\theta_0 \sim \mathcal{N}_p(m_0, C_0)$ with $m_0 \in \mathbb{R}^p$, $C_0$ a $p \times p$

\emph{Observation.} $Y_t \in \mathbb{R}^q$ (if $q = 1$ univariate).

\emph{State eq.} $\;\theta_t = \underbrace{G_t}_{p \times p}\, \theta_{t-1} + w_t, \qquad w_t \overset{\mathrm{iid}}{\sim} \mathcal{N}_p\bigl(0,\, \underbrace{W_t}_{p \times p}\bigr).$

\emph{Obs eq.} $\;Y_t = \underbrace{F_t}_{q \times p}\, \theta_t + v_t, \qquad v_t \overset{\mathrm{iid}}{\sim} \mathcal{N}_q\bigl(0,\, \underbrace{V_t}_{q \times q}\bigr).$

\emph{Independence.} $\{w_t\}, \{v_s\}, \theta_0$ mutually independent

\end{keydef}

\begin{keydef}
\fcnum{15c} \textbf{Worked check: is a concrete process Markov?} Take the random walk $Y_t = \sum_{i=1}^{t} Z_i$ with $Z_i$ i.i.d.\ and $Y_0 = 0$ (say $P(Z_i = -1) = p$, $P(Z_i = 1) = 1 - p$). Answer: YES. Rewrite it in one-step form $Y_t = Y_{t-1} + Z_t$. Because $Z_t$ is independent of the whole past $Y_{0:t-1}$, conditioning on the entire history is the same as conditioning on $Y_{t-1}$ alone:
$$ p(y_t \mid y_{0:t-1}) \;=\; p(Z_t = y_t - y_{t-1}) \;=\; p(y_t \mid y_{t-1}), $$
which is exactly the Markov property. 
\end{keydef}

