$$ \omark{\bar Y_{\text{July}} \;\approx\; \mathcal{N}\!\Bigl(0.35,\; \frac{0.35 \cdot 0.65}{1000}\Bigr), \qquad \sigma \;\approx\; 0.015.} $$

\textcolor{orange}{\textbf{Step 3 --- evaluate the tail.}}
$$ \omark{\hat q \;=\; \Prob{\bar Y_{\text{July}} > 0.5} \;\approx\; 1 - \Phi\!\Bigl(\frac{0.5 - 0.35}{0.015}\Bigr) \;=\; 1 - \Phi(10) \;\approx\; 0.} $$
\textcolor{orange}{Robustness: under any consistent reading of the panel size ($100$, $500$ or $1000$), the estimated July YES share $0.35$ is far below $50\%$, so $\hat q \approx 0$ either way.}


