\textbf{\textcolor{red}{INFERENCE FOR MARKOV CHAINS}} \emph{(panel of i.i.d.\ chains)}

\begin{keydef}
\fcnum{18a} 0. \textbf{Setting}: $n$ trajectories (chains) observed T times: $ y_{1:n,0:T}$, $k = 1, 2... n$ individuals. 

1. \textbf{Modelling assumptions:}  M1) each chain is homogeneous Markov, M2) individuals k are independent = chains are independent\textcolor{orange}{, and identically distributed, with common transition matrix $\mathbf{P}$}


2. \textbf{Write the likelihood.}

$$ \underbrace{L(\mathbf{P} | y_{1:n,0:T}) }_{\text{For every of the n individuals a chain long T}} \;\overset{(1)}{=}\; \underbrace{\prod_{k=1}^{n} P\bigl(Y_{k,1:T} \mid \underbrace{y_{k,0}}_{\text{init value for indiv k}}, \mathbf{P}\bigr)}_{(1)\ \ \text{iid across each indiv }k} \;\overset{(2)}{=}\; \underbrace{\prod_{k=1}^{n} \prod_{t=1}^{T} P\bigl(Y_{k,t} \mid y_{k,0:t-1}, \mathbf{P}\bigr)}_{(2)\ \text{expand $Y_{1:T}$ + chain rule (you've already seen this Product in T)}} \;\overset{(3)}{=}\; \underbrace{\prod_{k=1}^{n} \prod_{t=1}^{T} P\bigl(Y_{k,t} \mid y_{k,t-1}, \mathbf{P}\bigr)}_{(3)\ (M1)\ \text{Markov drops deep history}} \;\overset{(4)}{=}\; \underbrace{\prod_{k=1}^{n} \prod_{t=1}^{T} p_{y_{k,t-1},\, y_{k,t}}}_{\text{notation}}. $$   

Now regroup by transition counts\textcolor{orange}{. Define the matrix of transition counts $N = [n_{i,j}]$, where} $\omark{n_{i,j} \;=\; \#\bigl\{(k,t) : y_{k,t-1} = i,\; y_{k,t} = j\bigr\}}$ \textcolor{orange}{= number of observed transitions $i \to j$, pooled over individuals $k = 1,\dots,n$ and times $t = 1,\dots,T$;} \textcolor{orange}{its row totals $n_{i,+} = \sum_{j} n_{i,j}$ count the departures from state $i$. Then:} $$ \prod_{i=1}^{M}\prod_{j=1}^{M} \underbrace{p_{i,j}^{\, n_{i,j}}}_{g(T(x), \theta)}. $$ So the statistic $T(x) = \{n_{i,j}\}$ is \textbf{jointly sufficient} for $\mathbf{P}$ . *See note about the exponent. 

3.** Find the MLE**
\textbf{i) take logs.} Products are painful to differentiate; logs turn them into sums, and since $\log$ is monotonic the maximizer doesn't change. So:
$$ \ell(\mathbf{P}) \;=\; \sum_{i,j} n_{ij}\,\log p_{ij}. $$

\textbf{ii) --- Lagrangian for one row (each row is independent).} For row $i$ you want to maximize $\sum_j n_{ij}\log p_{ij}$ subject to $\sum_j p_{ij}=1$: 
$$ \mathcal{L}_i \;=\; \sum_j n_{ij}\log p_{ij} \;-\; \lambda_i\Bigl(\sum_j p_{ij} - 1\Bigr). $$
Differentiate: $$ \frac{\partial \mathcal{L}_i}{\partial p_{ij}} \;=\; \frac{n_{ij}}{p_{ij}} - \lambda_i \;=\; 0 \quad\Longrightarrow\quad p_{ij} \;=\; \frac{n_{ij}}{\lambda_i}. $$

From the (probability budget) constraint: 
$$ 1 \;=\; \sum_j p_{ij} \;=\; \sum_j \frac{n_{ij}}{\lambda_i} \;=\; \frac{1}{\lambda_i}\sum_j n_{ij} \;=\; \frac{n_{i,+}}{\lambda_i} \quad\Longrightarrow\quad \lambda_i \;=\; n_{i,+}. $$
Hence: 
$$ \boxed{\;\hat{p}_{ij} \;=\; \frac{n_{ij}}{n_{i,+}}\;} $$

\end{keydef}

\begin{keydef}
\fcnum{18b} \textcolor{orange}{\textbf{Conditional independence along the chain (June 2026 Q2b; June 2025 Q1b; Misc 11.1.1 Q3).}} \textcolor{orange}{Claim: for a Markov chain and any lag $k \ge 1$,} $\omark{Y_t \;\perp\!\!\!\perp\; (Y_1, \dots, Y_{t-k-1}) \mid Y_{t-k}}$\textcolor{orange}{. The exams ask $k = 1$ (given $Y_{t-1}$), $k = 2$ (given $Y_{t-2}$) and $k = 3$ (given $Y_{t-3}$); the answer is YES in every case.}

\textcolor{orange}{\emph{d-separation criterion.} In a DAG, two sets of nodes are conditionally independent given a set $C$ if every path between them is blocked by $C$:} \textcolor{orange}{a path is blocked when it contains a serial (chain) or diverging node inside $C$, or a collider outside $C$ with no descendant in $C$.}

\textcolor{orange}{\emph{Graphical proof.} The DAG of a Markov chain is the single directed line} $\omark{Y_0 \to Y_1 \to \dots \to Y_{t-k} \to \dots \to Y_t}$\textcolor{orange}{. The only path from any $Y_s$ with $s \le t-k-1$ to $Y_t$ runs along this line, hence necessarily crosses $Y_{t-k}$, which sits on it as a serial node --- not a collider --- and belongs to the conditioning set, so the path is blocked.} \textcolor{orange}{Thus $Y_{t-k}$ d-separates $Y_t$ from $(Y_1, \dots, Y_{t-k-1})$, and d-separation implies conditional independence for a joint law that factorizes along the DAG.} $\omark{\square}$
\end{keydef}

\textcolor{orange}{\textbf{``Markov chains are stationary'' --- NO (May 2026 Q2b).}} \textcolor{orange}{Counterexample: the flip chain on $\{1, 2\}$ with $p_{1,2} = p_{2,1} = 1$, started at $Y_0 = 1$.} \textcolor{orange}{Then $P(Y_n = 1) = 1$ for even $n$ and $0$ for odd $n$: the marginal law of $Y_n$ changes with $n$, so the process is not stationary (the marginals are not even identically distributed).} \textcolor{orange}{A Markov chain is stationary only if started from an invariant distribution $\pi = \pi \mathbf{P}$ (for the flip chain, $\pi = (1/2, 1/2)$); in general the marginals evolve with $t$ --- see node ``Ergodic properties of a Markov chain (Theorem 2.1)''.}

\textcolor{orange}{\textbf{Application (June 2025 Q2e): point estimate of the election probability.}}

\textcolor{orange}{Data (exam p.\ 9): a panel is interviewed monthly from January ($t=0$) to June ($t=5$); states $1=$ YES, $2=$ NO, $3=$ Uncertain.} \textcolor{orange}{Target:} $\omark{q \;=\; \Prob{\text{July YES share} > 50\%}}$\textcolor{orange}{.}

\textcolor{orange}{The exam table is a \emph{pooled} transition-count table: the $n_{ij}$ of this keydef, summed over all transitions $t = 1,\dots,5$.} \textcolor{orange}{Its grand total is $500 = 100 \times 5$ (the model text sets $k = 1,\dots,100$ chains, although the exam intro says $n = 1000$ individuals --- an internal inconsistency of the exam text).} \textcolor{orange}{Hence the row totals $(n_{1,+}, n_{2,+}, n_{3,+}) = (150, 250, 100)$ count \emph{departures} from each state at times $t = 0,\dots,4$ (Jan--May occupancy pooled over chains); they are \emph{not} the June ($t=5$) state counts, which sit inside the columns and cannot be recovered from the table.}

\textcolor{orange}{\textbf{Step 1 --- counts-ratio MLEs and one-step propagation.}} \textcolor{orange}{From the boxed MLE: $70/150 = 0.467$, $75/250 = 0.300$, $30/100 = 0.300$.} \textcolor{orange}{Use the pooled occupancy mix $(150, 250, 100)/500$ as a \emph{proxy} for the current-state distribution and push it one step through the estimated matrix:}
$$ \omark{\hat p_{\text{YES}} \;=\; \frac{150\cdot\frac{70}{150} \;+\; 250\cdot\frac{75}{250} \;+\; 100\cdot\frac{30}{100}}{500} \;=\; \frac{70 + 75 + 30}{500} \;=\; \frac{175}{500} \;=\; 0.35.} $$

\textcolor{orange}{\textbf{Step 2 --- CLT for the July proportion.}} \textcolor{orange}{Each of the i.i.d.\ panellists votes YES in July with estimated probability $0.35$; taking the exam's stated panel size $n = 1000$, the July share is approximately}
$$ \omark{\bar Y_{\text{July}} \;\approx\; \mathcal{N}\!\Bigl(0.35,\; \frac{0.35 \cdot 0.65}{1000}\Bigr), \qquad \sigma \;\approx\; 0.015.} $$

\textcolor{orange}{\textbf{Step 3 --- evaluate the tail.}}
$$ \omark{\hat q \;=\; \Prob{\bar Y_{\text{July}} > 0.5} \;\approx\; 1 - \Phi\!\Bigl(\frac{0.5 - 0.35}{0.015}\Bigr) \;=\; 1 - \Phi(10) \;\approx\; 0.} $$
\textcolor{orange}{Robustness: under any consistent reading of the panel size ($100$, $500$ or $1000$), the estimated July YES share $0.35$ is far below $50\%$, so $\hat q \approx 0$ either way.}


\textit{Caveats one may want to relax:} higher-order Markov (memory $r > 1$); non-homogeneity ($\mathbf{P}_t$ depends on $t$); individual-specific transition matrices (heterogeneity).


*Coin flip, outcome: H, H, T, H. Probability of this exact sequence:$$p \cdot p \cdot (1-p) \cdot p \;=\; p^{3} \cdot (1-p)^{1}.$$ In short: $$\text{exponent on } p_{i,j} = \text{how many times you observed the transition } i \to j.$$

\textbf{\textcolor{red}{2. ESTIMATION OF THE UNKNOWN PARAMETERS}}

\begin{keydef}
\fcnum{26} 
\textcolor{orange}{\textbf{Parameters.} Stating that the unknown parameters are} $\omark{\phi = (\pi,\, P,\, B)}$ \textcolor{orange}{(initial distribution, transition matrix, emission matrix) is correct only for the generic categorical HMM; two exam caveats:} \textcolor{orange}{(i) $\pi$ belongs to $\phi$ only when the initial law is left unspecified by the model --- May 2023 Q3a fixes $S_0 = 1$ and May 2022 Q6a assumes a uniform initial distribution, so there $\pi$ is known and must be excluded from the parameter list (likewise June 2025 Q2b: initial values fixed, so the initial probabilities are treated as known);} \textcolor{orange}{(ii) the emission block is an emission \emph{matrix} $B$ only for categorical emissions --- with parametric emissions it is the vector of emission parameters, e.g. state-dependent Gaussian variances $\sigma^2_1, \dots, \sigma^2_k$ (May 2023 Q3, May 2022 Q6) or Poisson rates $\lambda_1, \lambda_2, \lambda_3$ (May 2021 Q4b).}

\textbf{\textcolor{red}{1. Writing the Likelihood}}
$$L(\phi \mid y_{1:T}) \;=\;  p(y_{1:T} \mid \phi) \;\underbrace{=}_{\text{marginalization}}\; \sum_{s_{0:T} \,\in\, \{1, \dots, K\}^{T+1}} p(y_{1:T},\, s_{0:T} \mid \phi) \;\underbrace{=}_{\text{chain rule}}\; \sum_{s_{0:T} \,\in\, \{1, \dots, K\}^{T+1}} \underbrace{p(y_{1:T} \mid s_{0:T},\, \phi)}_{(\mathrm{A})\,\text{ obs.\ given path}} \;\cdot\; \underbrace{p(s_{0:T} \mid \phi)}_{(\mathrm{B})\,\text{ path probability}} \; $$

\textcolor{orange}{Observation term (emission product) --- the original label \emph{Decoding} here was wrong; decoding (inferring the latent path) is a separate task, see node \emph{Smoothing and decoding}.}
$$ (\mathrm{A}) \;=\; p(y_{1:T} \mid s_{0:T},\, \phi) \;\underbrace{=}_{\text{unpack slice}}\; p(y_1,\, y_2,\, \dots,\, y_T \mid s_{0:T},\, \phi) \;\underbrace{=}_{\text{Open}}\; \prod_{t=1}^{T} p(y_t \mid y_{1:t-1},\, s_{0:T},\, \phi) \;\underbrace{=}_{\text{emission CI}}\; \prod_{t=1}^{T} p(y_t \mid s_t,\, \phi) \;=\; \prod_{t=1}^{T} b_{s_t, y_t}. $$
Transition probabilities:
$$ (\mathrm{B}) \;=\; p(s_{0:T} \mid \phi) \;\underbrace{=}_{\text{unpack slice}}\; p(s_0,\, s_1,\, \dots,\, s_T \mid \phi) \;\underbrace{=}_{\text{Open}}\; p(s_0 \mid \phi) \prod_{t=1}^{T} p(s_t \mid s_{0:t-1},\, \phi) \;\underbrace{=}_{\text{Markov}}\; p(s_0 \mid \phi) \prod_{t=1}^{T} p(s_t \mid s_{t-1},\, \phi) \;=\; \pi_{s_0} \prod_{t=1}^{T} p_{s_{t-1}, s_t}. $$

$$ \boxed{\; L(\phi \mid y_{1:T}) \;=\; \sum_{s_{0:T} \,\in\, \{1, \dots, K\}^{T+1}} \underbrace{\pi_{s_0}}_{\text{initial}} \;\cdot\; \underbrace{\prod_{t=1}^{T} p_{s_{t-1}, s_t}}_{\text{transitions}} \;\cdot\; \underbrace{\prod_{t=1}^{T} b_{s_t, y_t}}_{\text{emissions}}  \;=\; \sum_{s_{0:T}} \pi_{s_0}\, p_{s_0, s_1}\, b_{s_1, y_1}\, p_{s_1, s_2}\, b_{s_2, y_2}\, \cdots\, p_{s_{T-1}, s_T}\, b_{s_T, y_T}\;} $$

\textcolor{orange}{The entry} $b_{s_t, y_t}$ \textcolor{orange}{is a placeholder for a generic emission density: with parametric emissions the identical derivation (marginalisation, chain rule, Markov, emission CI) gives}
$$ \omark{L(\phi \mid y_{1:T}) \;=\; \sum_{s_{0:T}} \pi_{s_0} \prod_{t=1}^{T} p_{s_{t-1}, s_t} \prod_{t=1}^{T} f(y_t \mid \theta^*_{s_t}), \qquad \text{e.g. Poisson: } f(y \mid \lambda_j) = \frac{e^{-\lambda_j}\, \lambda_j^{y}}{y!}} $$
\textcolor{orange}{as required by May 2021 Q4c (Poisson, $k = 3$), May 2023 Q3 / May 2022 Q6 (Gaussian $N(0, \sigma^2_j)$), June 2025 Extra Q2 (Bernoulli); see node \emph{State space models (SSM)} for state-dependent parametric emissions.}

\textbf{\textcolor{red}{2. Maximisation}} The MLE is $\hat\phi = \arg\max_{\phi} L(\phi \mid y_{1:T})$. Direct numerical maximisation is feasible but expensive; in practice, the EM algorithm (\emph{Baum-Welch} for HMMs) is the standard iterative procedure.

\textcolor{orange}{The raw sum has $K^{T+1}$ terms; evaluate $L$ efficiently via the forward algorithm --- see node \emph{Decoding / filtering}.}

\textcolor{orange}{\textbf{Standard errors} (asked in June 2025 Extra Q2b, June 2024 Extra Qa.ii, May 2025 Extra Q1): by asymptotic normality of the MLE,}
$$ \omark{\widehat{\Var}(\hat\phi) \;=\; \mathcal{J}(\hat\phi)^{-1}, \qquad \mathcal{J}(\hat\phi) \;=\; -\, \frac{\partial^2 \log L(\phi \mid y_{1:T})}{\partial \phi\, \partial \phi'} \bigg|_{\phi = \hat\phi}, \qquad \mathrm{SE}(\hat\phi_r) \;=\; \sqrt{\big[ \mathcal{J}(\hat\phi)^{-1} \big]_{rr}}} $$
\textcolor{orange}{i.e. the inverse observed information (numerical Hessian of the negative log-likelihood at the optimum). Note: EM (Baum-Welch) alone does not produce standard errors; the Hessian step is still needed.}

\textcolor{orange}{DLM case: for a (Gaussian) DLM the likelihood is instead computed by prediction-error decomposition via the Kalman filter (DLMwR Sec. 4.1) --- see nodes \emph{Parameter Estimation} and \emph{Estimation of unknown parameters --- DLM (prediction-error decomposition)}.}
\end{keydef}

\textbf{\textcolor{red}{PARAMETER ESTIMATION}}

\begin{keydef}
\fcnum{24} Estimate the \emph{fixed}, time-invariant constants $\phi$ of the model from data $y_{1:T}$. Two routes: \emph{maximum likelihood} (frequentist) or \emph{Bayesian inference}.

\textcolor{orange}{\textbf{The likelihood (prediction-error decomposition).}} \textcolor{orange}{By the product rule,}
$$ \omark{L(\phi) \;=\; f(y_{1:T} \mid \phi) \;=\; \prod_{t=1}^{T} f(y_t \mid y_{1:t-1}, \phi)}. $$
\textcolor{orange}{For a DLM each factor is Gaussian, with the one-step-ahead forecast moments $(f_t, Q_t)$ delivered by the Kalman filter run at $\phi$ (DLMwR eqs. 4.1--4.2):}
$$ \omark{L(\phi) \;=\; \prod_{t=1}^{T} \mathcal{N}\big(y_t;\, f_t(\phi),\, Q_t(\phi)\big), \qquad \ell(\phi) \;=\; -\tfrac12 \sum_{t=1}^{T} \log\abs{Q_t} \;-\; \tfrac12 \sum_{t=1}^{T} (y_t - f_t)' Q_t^{-1} (y_t - f_t)}. $$

Two approaches
$\bullet$ \emph{Frequentist}: maximise the likelihood over $\phi$ to get the MLE $\hat\phi$. \textcolor{orange}{Concretely $\hat\phi = \arg\max_\phi \ell(\phi)$ by numerical optimization (e.g. BFGS).} A note on identifiability: two parameter values $\phi_1 \neq \phi_2$ may give the SAME likelihood for every possible dataset. Then the $\arg\max$ is not unique --- the model is \emph{not identifiable}. Prefer the more parsimonious model.

\textcolor{orange}{\emph{The plug-in procedure and its caveat (exam June 2026 Q7a; DLMwR pp. 143, 148).} In the classical framework, after computing the MLE $\hat\phi$ one plugs it into the model and applies the Chapter-2 filtering / smoothing / forecasting recursions as if $\phi$ were a known constant.} \textcolor{orange}{This common practice suffers from the difficulty of taking properly into account the uncertainty about $\phi$: every output treats $\hat\phi$ as exact, so the resulting predictive intervals understate the total uncertainty --- they are too narrow.}

$\bullet$ \emph{Bayesian inference for $\phi$.} \textcolor{orange}{Treat $\phi$ as random with a prior $\pi(\phi)$; the model assumptions (Markov states, conditional independence of the $Y_t$ given the states) hold \emph{conditionally on} $\phi$.} \textcolor{orange}{Marginally --- with $\phi$ integrated out --- the classic properties are lost: the state process is no longer Markov and the observations are no longer conditionally i.i.d., because averaging over $\pi(\phi)$ ties all time points together.} \textcolor{orange}{Every ingredient --- $F_t, G_t, V_t, W_t$ and the prior of $\theta_0$ --- may depend on $\phi$.} \textcolor{orange}{Posterior:}
$$ \omark{f(\phi \mid y_{1:T}) \;\propto\; f(y_{1:T} \mid \phi)\, f(\phi)}, $$
\textcolor{orange}{generally not analytically manageable outside conjugate special cases $\Rightarrow$ MCMC: Gibbs sampling on the augmented $(\theta_{0:T}, \phi)$, alternating the full conditionals $\pi(\theta_{0:T} \mid \phi, y_{1:T})$ (drawn by FFBS) and $\pi(\phi \mid \theta_{0:T}, y_{1:T})$.} \textcolor{orange}{\emph{The joint density of the data (exam June 2024 Q7).} Frequentist: $p(y_{1:n}; \phi) = \prod_t p(y_t \mid y_{1:t-1}; \phi)$ (DLMwR eq. 4.1) \emph{does} depend on the unknown $\phi$.} \textcolor{orange}{Bayesian: $\phi$ is integrated out against its prior, giving the \emph{prior predictive} (evidence)}
$$ \omark{p(y_{1:n}) \;=\; \int p(y_{1:n} \mid \phi)\, \pi(\phi)\, d\phi \;=\; \int \Big[ \prod_{t=1}^{n} \mathcal{N}\big(y_t;\, f_t(\phi),\, Q_t(\phi)\big) \Big] \pi(\phi)\, d\phi} $$
\textcolor{orange}{--- a number free of $\phi$: the normalizing constant of the posterior $f(\phi \mid y_{1:n})$.} \textcolor{orange}{Predictives marginalise $\phi$ out:}
$$ \omark{f(y_t \mid y_{1:t-1}) \;=\; \int f(y_t \mid y_{1:t-1}, \phi)\, f(\phi \mid y_{1:t-1})\, d\phi} $$
\textcolor{orange}{--- a mixture of Gaussians.} \textcolor{orange}{\emph{Comment (exam June 2025 Q6, May 2025 Q6b).} Both the predictive and the filtering marginals are \emph{mixtures} of Gaussians, not Gaussian.} \textcolor{orange}{Mixing over the posterior of $\phi$ propagates parameter uncertainty into the answer, so these densities are more dispersed than the plug-in Gaussian $\mathcal{N}(f_t(\hat\phi),\, Q_t(\hat\phi))$, which treats $\hat\phi$ as exact.}

\textcolor{orange}{\emph{MCMC --- the basic idea (exam May 2022 Q8b, Misc 11.3 Q1d).} To approximate an intractable target distribution $\pi$ (here the joint posterior of states and parameters), construct an \emph{ergodic} (irreducible, aperiodic, recurrent) Markov chain whose transition kernel is designed to have $\pi$ as its unique \emph{invariant (stationary) distribution}.} \textcolor{orange}{By the ergodic theorem the chain converges to $\pi$ from any initialization: after a burn-in, the simulated path yields approximate draws from $\pi$, and ergodic averages approximate expectations under $\pi$; Gibbs sampling builds such a kernel by cycling through the full conditionals.} \textcolor{orange}{(Convergence theory: see node "Ergodic properties of a Markov chain (Theorem 2.1)"; the invariant-distribution formulation of MCMC is covered in DLMwR Sec. 1.6, pp. 22--24: convergence and ergodic averages, eqs. 1.13--1.14, and the Gibbs sampler, Algorithm 1.1.)}

\textcolor{orange}{\textbf{Bayesian filtering and prediction with unknown $\phi$ --- mixture-of-Gaussians marginalisation.}}

\textcolor{orange}{\emph{Derivation (DLMwR eq. 4.7).} The joint posterior factorises; integrating $\phi$ out leaves the conditional averaged over the posterior of $\phi$:}
$$ \omark{\pi(\theta_s, \phi \mid y_{1:t}) \;=\; \pi(\theta_s \mid \phi, y_{1:t})\; \pi(\phi \mid y_{1:t}) \quad\Longrightarrow\quad \pi(\theta_s \mid y_{1:t}) \;=\; \int \pi(\theta_s \mid \phi, y_{1:t})\; \pi(\phi \mid y_{1:t})\, d\phi} $$
\textcolor{orange}{($s = t$ filtering, $s > t$ state prediction, $s < t$ smoothing).}

\textcolor{orange}{\emph{Filtering ($s = t$).} The Chapter-2 KF recursions compute the \emph{conditional} density $\pi(\theta_t \mid \phi, y_{1:t})$; it is now \emph{averaged} with respect to the posterior of $\phi$ given the data:}
$$ \omark{\pi(\theta_t \mid y_{1:t}) \;=\; \int \underbrace{\mathcal{N}_p\big(\theta_t;\; m_t(\phi),\; C_t(\phi)\big)}_{\text{KF at fixed } \phi}\; \pi(\phi \mid y_{1:t})\, d\phi.} $$

\textcolor{orange}{\emph{Predictive, explicitly.} For each fixed $\phi$ the KF delivers the Gaussian one-step forecast:}
$$ \omark{p(y_t \mid y_{1:t-1}) \;=\; \int \mathcal{N}\big(y_t;\; f_t(\phi),\; Q_t(\phi)\big)\; p(\phi \mid y_{1:t-1})\, d\phi.} $$

\textcolor{orange}{\emph{MCMC approximation of the mixture.} Draw $\phi^{(1)}, \dots, \phi^{(S)}$ from the posterior by the Gibbs sampler above, run the KF at each draw, and average the resulting Gaussians:}
$$ \omark{p(y_t \mid y_{1:t-1}) \;\approx\; \frac{1}{S} \sum_{s=1}^{S} \mathcal{N}\big(y_t;\; f_t(\phi^{(s)}),\; Q_t(\phi^{(s)})\big).} $$
\textcolor{orange}{\emph{Limitation --- no on-line updating (DLMwR "Filtering and on-line forecasting").} MCMC output is not recursive: when a new observation $y_{t+1}$ arrives, the target becomes $\pi(\theta_{0:t+1}, \phi \mid y_{1:t+1})$ and the whole MCMC must be rerun.}

The Bayesian analogue of the MLE is the \emph{maximum a posteriori}: pick the $\phi$ that maximises the \emph{posterior} (not the likelihood):
$$ \hat\phi_{\mathrm{MAP}} \;=\; \arg\max_\phi\, f(\phi \mid y_{1:T}) \;=\; \arg\max_\phi\, \underbrace{f(y_{1:T} \mid \phi)}_{\text{likelihood}} \cdot \underbrace{f(\phi)}_{\text{prior}}. $$
\emph{MAP as a compromise.} The MAP is the $\phi$ that scores highest on the \textbf{product} of (a) how plausible it was a priori $f(\phi)$ and (b) how well it explains the observed data $f(y_{1:T} \mid \phi)$.
\end{keydef}

\textbf{\textcolor{red}{WRITING THE LIKELIHOOD OF A DLM WITH UNKNOWN $\phi$ --- prediction-error decomposition.}}

\begin{keydef}
\fcnum{25} 
\textbf{\textcolor{red}{1. Chain rule (pure probability identity, no model assumption).}}
$$ L(\phi \mid y_{1:T}) = p(y_{1:T} \mid \phi) \;\underbrace{=}_{\text{chain rule in time}}\; \prod_{t=1}^{T} \underbrace{p(y_t \mid y_{1:t-1}, \phi)}_{\mathcal{N}_q\bigl(y_t;\; f_t(\phi),\; Q_t(\phi)\bigr)^{*1}} $$

*\emph{Why Gaussian:} $Y_t = F_t\, \theta_t + v_t$ is a linear combination of $\theta_t \mid y_{1:t-1} \sim \mathcal{N}(a_t, R_t)$ and independent $v_t \sim \mathcal{N}(0, V_t)$

\textbf{\textcolor{red}{4. Log-likelihood (just take logs of the Gaussian densities).}}
Define the innovation $e_t = y_t - f_t(\phi)$ and sum over $t$:
$$ \boxed{\; -2\log L(\phi) \;=\; \sum_{t=1}^{T}\Bigl[\,q\log(2\pi) \;+\; \log|Q_t(\phi)| \;+\; e_t^\top\, Q_t(\phi)^{-1}\, e_t\,\Bigr]. \;} $$
\emph{This is the likelihood the exam wants you to write.} 

\textcolor{orange}{Book form (DLMwR eq.~(4.2), p.~144): the likelihood is defined only \emph{up to a constant factor}, so the per-term additive constant $q\log(2\pi)$ is dropped and one maximizes the constant-free log-likelihood}
$$ \omark{\ell(\phi) \;=\; -\tfrac12 \sum_{t=1}^{T} \log\abs{Q_t(\phi)} \;-\; \tfrac12 \sum_{t=1}^{T} e_t^\top\, Q_t(\phi)^{-1}\, e_t,} $$
\textcolor{orange}{as used in the sibling \emph{Parameter Estimation} node; dropping this constant does not change the maximizer $\hat\phi$.}

\emph{MLE footnote.} MLE needs numericql maximization: BFGS / Nelder-Mead.

\textcolor{orange}{\textbf{Standard errors of the MLE} (asked for a DLM in May 2025 Extra Q3, June 2024 Extra Qc.ii and the May 2024 Q7 no-assignment box). Let $H$ be the Hessian of the negative log-likelihood $-\ell$ evaluated at $\hat\phi$ (DLMwR p.~144); then $H^{-1}$ estimates $\Var(\hat\phi)$, so}
$$ \omark{H \;=\; -\, \frac{\partial^2 \ell(\phi)}{\partial\phi\, \partial\phi'}\bigg|_{\phi=\hat\phi}, \qquad \mathrm{SE}(\hat\phi_r) \;=\; \sqrt{\big[H^{-1}\big]_{rr}}.} $$
\textcolor{orange}{In R, get $H$ from the optimizer (\texttt{optim(..., hessian=TRUE)} or \texttt{dlmMLE(..., hessian=TRUE)}) and take \texttt{sqrt(diag(solve(H)))}.}
\end{keydef}

\textbf{\textcolor{red}{INFERENCE FOR MARKOV CHAINS}} \emph{(panel of i.i.d.\ chains)}

\begin{keydef}
\fcnum{18a} 0. \textbf{Setting}: $n$ trajectories (chains) observed T times: $ y_{1:n,0:T}$, $k = 1, 2... n$ individuals. 

1. \textbf{Modelling assumptions:}  M1) each chain is homogeneous Markov, M2) individuals k are independent = chains are independent\textcolor{orange}{, and identically distributed, with common transition matrix $\mathbf{P}$}


2. \textbf{Write the likelihood.}

$$ \underbrace{L(\mathbf{P} | y_{1:n,0:T}) }_{\text{For every of the n individuals a chain long T}} \;\overset{(1)}{=}\; \underbrace{\prod_{k=1}^{n} P\bigl(Y_{k,1:T} \mid \underbrace{y_{k,0}}_{\text{init value for indiv k}}, \mathbf{P}\bigr)}_{(1)\ \ \text{iid across each indiv }k} \;\overset{(2)}{=}\; \underbrace{\prod_{k=1}^{n} \prod_{t=1}^{T} P\bigl(Y_{k,t} \mid y_{k,0:t-1}, \mathbf{P}\bigr)}_{(2)\ \text{expand $Y_{1:T}$ + chain rule (you've already seen this Product in T)}} \;\overset{(3)}{=}\; \underbrace{\prod_{k=1}^{n} \prod_{t=1}^{T} P\bigl(Y_{k,t} \mid y_{k,t-1}, \mathbf{P}\bigr)}_{(3)\ (M1)\ \text{Markov drops deep history}} \;\overset{(4)}{=}\; \underbrace{\prod_{k=1}^{n} \prod_{t=1}^{T} p_{y_{k,t-1},\, y_{k,t}}}_{\text{notation}}. $$   

Now regroup by transition counts\textcolor{orange}{. Define the matrix of transition counts $N = [n_{i,j}]$, where} $\omark{n_{i,j} \;=\; \#\bigl\{(k,t) : y_{k,t-1} = i,\; y_{k,t} = j\bigr\}}$ \textcolor{orange}{= number of observed transitions $i \to j$, pooled over individuals $k = 1,\dots,n$ and times $t = 1,\dots,T$;} \textcolor{orange}{its row totals $n_{i,+} = \sum_{j} n_{i,j}$ count the departures from state $i$. Then:} $$ \prod_{i=1}^{M}\prod_{j=1}^{M} \underbrace{p_{i,j}^{\, n_{i,j}}}_{g(T(x), \theta)}. $$ So the statistic $T(x) = \{n_{i,j}\}$ is \textbf{jointly sufficient} for $\mathbf{P}$ . *See note about the exponent. 

3.** Find the MLE**
\textbf{i) take logs.} Products are painful to differentiate; logs turn them into sums, and since $\log$ is monotonic the maximizer doesn't change. So:
$$ \ell(\mathbf{P}) \;=\; \sum_{i,j} n_{ij}\,\log p_{ij}. $$

\textbf{ii) --- Lagrangian for one row (each row is independent).} For row $i$ you want to maximize $\sum_j n_{ij}\log p_{ij}$ subject to $\sum_j p_{ij}=1$: 
$$ \mathcal{L}_i \;=\; \sum_j n_{ij}\log p_{ij} \;-\; \lambda_i\Bigl(\sum_j p_{ij} - 1\Bigr). $$
Differentiate: $$ \frac{\partial \mathcal{L}_i}{\partial p_{ij}} \;=\; \frac{n_{ij}}{p_{ij}} - \lambda_i \;=\; 0 \quad\Longrightarrow\quad p_{ij} \;=\; \frac{n_{ij}}{\lambda_i}. $$

From the (probability budget) constraint: 
$$ 1 \;=\; \sum_j p_{ij} \;=\; \sum_j \frac{n_{ij}}{\lambda_i} \;=\; \frac{1}{\lambda_i}\sum_j n_{ij} \;=\; \frac{n_{i,+}}{\lambda_i} \quad\Longrightarrow\quad \lambda_i \;=\; n_{i,+}. $$
Hence: 
$$ \boxed{\;\hat{p}_{ij} \;=\; \frac{n_{ij}}{n_{i,+}}\;} $$

\end{keydef}

\begin{keydef}
\fcnum{18b} \textcolor{orange}{\textbf{Conditional independence along the chain (June 2026 Q2b; June 2025 Q1b; Misc 11.1.1 Q3).}} \textcolor{orange}{Claim: for a Markov chain and any lag $k \ge 1$,} $\omark{Y_t \;\perp\!\!\!\perp\; (Y_1, \dots, Y_{t-k-1}) \mid Y_{t-k}}$\textcolor{orange}{. The exams ask $k = 1$ (given $Y_{t-1}$), $k = 2$ (given $Y_{t-2}$) and $k = 3$ (given $Y_{t-3}$); the answer is YES in every case.}

\textcolor{orange}{\emph{d-separation criterion.} In a DAG, two sets of nodes are conditionally independent given a set $C$ if every path between them is blocked by $C$:} \textcolor{orange}{a path is blocked when it contains a serial (chain) or diverging node inside $C$, or a collider outside $C$ with no descendant in $C$.}

\textcolor{orange}{\emph{Graphical proof.} The DAG of a Markov chain is the single directed line} $\omark{Y_0 \to Y_1 \to \dots \to Y_{t-k} \to \dots \to Y_t}$\textcolor{orange}{. The only path from any $Y_s$ with $s \le t-k-1$ to $Y_t$ runs along this line, hence necessarily crosses $Y_{t-k}$, which sits on it as a serial node --- not a collider --- and belongs to the conditioning set, so the path is blocked.} \textcolor{orange}{Thus $Y_{t-k}$ d-separates $Y_t$ from $(Y_1, \dots, Y_{t-k-1})$, and d-separation implies conditional independence for a joint law that factorizes along the DAG.} $\omark{\square}$
\end{keydef}

\textcolor{orange}{\textbf{``Markov chains are stationary'' --- NO (May 2026 Q2b).}} \textcolor{orange}{Counterexample: the flip chain on $\{1, 2\}$ with $p_{1,2} = p_{2,1} = 1$, started at $Y_0 = 1$.} \textcolor{orange}{Then $P(Y_n = 1) = 1$ for even $n$ and $0$ for odd $n$: the marginal law of $Y_n$ changes with $n$, so the process is not stationary (the marginals are not even identically distributed).} \textcolor{orange}{A Markov chain is stationary only if started from an invariant distribution $\pi = \pi \mathbf{P}$ (for the flip chain, $\pi = (1/2, 1/2)$); in general the marginals evolve with $t$ --- see node ``Ergodic properties of a Markov chain (Theorem 2.1)''.}

\textcolor{orange}{\textbf{Application (June 2025 Q2e): point estimate of the election probability.}}

\textcolor{orange}{Data (exam p.\ 9): a panel is interviewed monthly from January ($t=0$) to June ($t=5$); states $1=$ YES, $2=$ NO, $3=$ Uncertain.} \textcolor{orange}{Target:} $\omark{q \;=\; \Prob{\text{July YES share} > 50\%}}$\textcolor{orange}{.}

\textcolor{orange}{The exam table is a \emph{pooled} transition-count table: the $n_{ij}$ of this keydef, summed over all transitions $t = 1,\dots,5$.} \textcolor{orange}{Its grand total is $500 = 100 \times 5$ (the model text sets $k = 1,\dots,100$ chains, although the exam intro says $n = 1000$ individuals --- an internal inconsistency of the exam text).} \textcolor{orange}{Hence the row totals $(n_{1,+}, n_{2,+}, n_{3,+}) = (150, 250, 100)$ count \emph{departures} from each state at times $t = 0,\dots,4$ (Jan--May occupancy pooled over chains); they are \emph{not} the June ($t=5$) state counts, which sit inside the columns and cannot be recovered from the table.}

\textcolor{orange}{\textbf{Step 1 --- counts-ratio MLEs and one-step propagation.}} \textcolor{orange}{From the boxed MLE: $70/150 = 0.467$, $75/250 = 0.300$, $30/100 = 0.300$.} \textcolor{orange}{Use the pooled occupancy mix $(150, 250, 100)/500$ as a \emph{proxy} for the current-state distribution and push it one step through the estimated matrix:}
$$ \omark{\hat p_{\text{YES}} \;=\; \frac{150\cdot\frac{70}{150} \;+\; 250\cdot\frac{75}{250} \;+\; 100\cdot\frac{30}{100}}{500} \;=\; \frac{70 + 75 + 30}{500} \;=\; \frac{175}{500} \;=\; 0.35.} $$

\textcolor{orange}{\textbf{Step 2 --- CLT for the July proportion.}} \textcolor{orange}{Each of the i.i.d.\ panellists votes YES in July with estimated probability $0.35$; taking the exam's stated panel size $n = 1000$, the July share is approximately}
$$ \omark{\bar Y_{\text{July}} \;\approx\; \mathcal{N}\!\Bigl(0.35,\; \frac{0.35 \cdot 0.65}{1000}\Bigr), \qquad \sigma \;\approx\; 0.015.} $$

\textcolor{orange}{\textbf{Step 3 --- evaluate the tail.}}
$$ \omark{\hat q \;=\; \Prob{\bar Y_{\text{July}} > 0.5} \;\approx\; 1 - \Phi\!\Bigl(\frac{0.5 - 0.35}{0.015}\Bigr) \;=\; 1 - \Phi(10) \;\approx\; 0.} $$
\textcolor{orange}{Robustness: under any consistent reading of the panel size ($100$, $500$ or $1000$), the estimated July YES share $0.35$ is far below $50\%$, so $\hat q \approx 0$ either way.}


\textit{Caveats one may want to relax:} higher-order Markov (memory $r > 1$); non-homogeneity ($\mathbf{P}_t$ depends on $t$); individual-specific transition matrices (heterogeneity).


*Coin flip, outcome: H, H, T, H. Probability of this exact sequence:$$p \cdot p \cdot (1-p) \cdot p \;=\; p^{3} \cdot (1-p)^{1}.$$ In short: $$\text{exponent on } p_{i,j} = \text{how many times you observed the transition } i \to j.$$

\textbf{\textcolor{red}{WRITING THE LIKELIHOOD OF A DLM WITH UNKNOWN $\phi$ --- prediction-error decomposition.}}

\begin{keydef}
\fcnum{25} 
\textbf{\textcolor{red}{1. Chain rule (pure probability identity, no model assumption).}}
$$ L(\phi \mid y_{1:T}) = p(y_{1:T} \mid \phi) \;\underbrace{=}_{\text{chain rule in time}}\; \prod_{t=1}^{T} \underbrace{p(y_t \mid y_{1:t-1}, \phi)}_{\mathcal{N}_q\bigl(y_t;\; f_t(\phi),\; Q_t(\phi)\bigr)^{*1}} $$

*\emph{Why Gaussian:} $Y_t = F_t\, \theta_t + v_t$ is a linear combination of $\theta_t \mid y_{1:t-1} \sim \mathcal{N}(a_t, R_t)$ and independent $v_t \sim \mathcal{N}(0, V_t)$

\textbf{\textcolor{red}{4. Log-likelihood (just take logs of the Gaussian densities).}}
Define the innovation $e_t = y_t - f_t(\phi)$ and sum over $t$:
$$ \boxed{\; -2\log L(\phi) \;=\; \sum_{t=1}^{T}\Bigl[\,q\log(2\pi) \;+\; \log|Q_t(\phi)| \;+\; e_t^\top\, Q_t(\phi)^{-1}\, e_t\,\Bigr]. \;} $$
\emph{This is the likelihood the exam wants you to write.} 

\textcolor{orange}{Book form (DLMwR eq.~(4.2), p.~144): the likelihood is defined only \emph{up to a constant factor}, so the per-term additive constant $q\log(2\pi)$ is dropped and one maximizes the constant-free log-likelihood}
$$ \omark{\ell(\phi) \;=\; -\tfrac12 \sum_{t=1}^{T} \log\abs{Q_t(\phi)} \;-\; \tfrac12 \sum_{t=1}^{T} e_t^\top\, Q_t(\phi)^{-1}\, e_t,} $$
\textcolor{orange}{as used in the sibling \emph{Parameter Estimation} node; dropping this constant does not change the maximizer $\hat\phi$.}

\emph{MLE footnote.} MLE needs numericql maximization: BFGS / Nelder-Mead.

\textcolor{orange}{\textbf{Standard errors of the MLE} (asked for a DLM in May 2025 Extra Q3, June 2024 Extra Qc.ii and the May 2024 Q7 no-assignment box). Let $H$ be the Hessian of the negative log-likelihood $-\ell$ evaluated at $\hat\phi$ (DLMwR p.~144); then $H^{-1}$ estimates $\Var(\hat\phi)$, so}
$$ \omark{H \;=\; -\, \frac{\partial^2 \ell(\phi)}{\partial\phi\, \partial\phi'}\bigg|_{\phi=\hat\phi}, \qquad \mathrm{SE}(\hat\phi_r) \;=\; \sqrt{\big[H^{-1}\big]_{rr}}.} $$
\textcolor{orange}{In R, get $H$ from the optimizer (\texttt{optim(..., hessian=TRUE)} or \texttt{dlmMLE(..., hessian=TRUE)}) and take \texttt{sqrt(diag(solve(H)))}.}
\end{keydef}

